window.COURSE = {"title": "Forge Academy · Go", "updated": "2026-10-22", "hours": 288, "levels": [{"id": 1, "title": "Primeiros passos", "tag": "Fundamentos", "summary": "Entenda o que um programa faz e dê suas primeiras instruções em Go.", "skills": ["Ambiente", "Variáveis", "Lógica"], "project": "Cartão de apresentação no terminal", "deliverables": ["Programa que apresenta nome, objetivo e horas disponíveis.", "Cálculo de horas de estudo por mês.", "README com instalação e execução."], "rubric": ["Executa com go run .", "Você explica cada linha sem consultar.", "Nomes claros e código formatado."]}, {"id": 2, "title": "Dados e funções", "tag": "Fundamentos", "summary": "Organize informações em coleções e construa funções com contratos claros.", "skills": ["Funções", "Slices e maps", "Strings e Unicode"], "project": "Resumo de serviços em memória", "deliverables": ["Receber uma coleção de serviços.", "Calcular totais por categoria.", "Validar entradas vazias e valores inválidos."], "rubric": ["Funções pequenas com contratos explícitos.", "Casos vazio, único e repetido funcionam.", "Não depende da ordem de um map."]}, {"id": 3, "title": "Modelagem idiomática", "tag": "Intermediário", "summary": "Modele domínio com structs, métodos, interfaces e erros explícitos.", "skills": ["Structs", "Interfaces", "Errors"], "project": "Motor de regras de ordens de serviço", "deliverables": ["Tipos de OS e transições válidas.", "Erros com contexto e sem duplicar logs.", "Interface pequena para persistência."], "rubric": ["Estados inválidos são recusados.", "Regras não conhecem HTTP nem SQL.", "Erros preservam a causa."]}, {"id": 4, "title": "Ferramentas e bibliotecas", "tag": "Intermediário", "summary": "Construa comandos utilizáveis e aprenda os protocolos de I/O da biblioteca padrão.", "skills": ["Modules", "io e arquivos", "JSON e CLI"], "project": "CLI de exportação de ordens", "deliverables": ["Flags para filtrar e exportar dados.", "Saída JSON determinística e legível.", "Separação entre stdout, stderr e erros."], "rubric": ["README permite reproduzir a execução.", "Arquivos são fechados e erros tratados.", "Saída de dados não é misturada a logs."]}, {"id": 5, "title": "Testes e confiabilidade", "tag": "Intermediário", "summary": "Transforme requisitos em verificações que encontram regressões reais.", "skills": ["testing", "Table tests", "Fuzzing"], "project": "Regras financeiras com testes", "deliverables": ["Testes de limites e valores inválidos.", "Subtestes legíveis e teste de regressão.", "Uma propriedade verificada com fuzzing."], "rubric": ["Os testes falham quando uma regra é quebrada.", "Sem dependência de rede ou relógio real.", "Asserções verificam comportamento observável."]}, {"id": 6, "title": "Concorrência segura", "tag": "Avançado", "summary": "Coordene tarefas, cancelamento e acesso a estado compartilhado.", "skills": ["Goroutines", "Channels e context", "sync"], "project": "Processador de evidências", "deliverables": ["Fila com concorrência limitada.", "Cancelamento propagado até as tarefas.", "Teste de encerramento e execução com -race."], "rubric": ["Não deixa goroutines sem dono.", "Não usa Sleep como sincronização.", "Explica quem fecha cada canal."]}, {"id": 7, "title": "APIs com net/http", "tag": "Avançado", "summary": "Exponha serviços com contratos claros, limites e testes de ponta a ponta.", "skills": ["Handlers", "Clientes e middleware", "Segurança"], "project": "API de ordens de serviço", "deliverables": ["Rotas de criação, consulta e conclusão.", "Validação, erros JSON e testes de contrato.", "Autorização por recurso e limites de requisição."], "rubric": ["Códigos HTTP têm significado consistente.", "Contexto chega à operação.", "Uma identidade não acessa ordens de outra sem permissão."]}, {"id": 8, "title": "Banco e arquitetura", "tag": "Avançado", "summary": "Persista regras com transações e fronteiras que permitem evolução.", "skills": ["database/sql", "Transações", "Design de pacotes"], "project": "Persistência transacional da OS", "deliverables": ["Migrações versionadas e consultas parametrizadas.", "Confirmação de OS e baixa de estoque consistentes.", "Testes de integração e de isolamento."], "rubric": ["Parâmetros nunca viram SQL concatenado.", "Transação não vaza para outra conexão.", "Concorrência não duplica a baixa."]}, {"id": 9, "title": "Go moderno e abstrações", "tag": "Avançado", "summary": "Use generics e reflexão quando melhorarem contratos e simplicidade.", "skills": ["Generics", "Iteradores", "Reflection"], "project": "Biblioteca de coleções pequena", "deliverables": ["Uma função genérica com restrição justificada.", "Iterador que respeita interrupção do consumidor.", "Comparação com solução concreta e benchmarks."], "rubric": ["Não usa any para esconder falta de contrato.", "Explica a versão mínima dos recursos.", "Abstração reduz repetição sem ampliar acoplamento."]}, {"id": 10, "title": "Desempenho e runtime", "tag": "Especialista", "summary": "Investigue gargalos com evidência e entenda os limites do modelo de execução.", "skills": ["pprof e trace", "Alocações e GC", "Modelo de memória"], "project": "Investigação de desempenho", "deliverables": ["Carga reprodutível com resultados antes/depois.", "Perfis de CPU ou heap e hipótese documentada.", "Uma melhoria sem regressão de correção."], "rubric": ["Medições têm contexto e variabilidade.", "Sem otimizações por suposição.", "Pode explicar o custo e a mudança no perfil."]}, {"id": 11, "title": "Operação em produção", "tag": "Especialista", "summary": "Prepare o serviço para iniciar, falhar, ser observado e encerrar com previsibilidade.", "skills": ["Shutdown", "Observabilidade", "CI e entregas"], "project": "Serviço pronto para homologação", "deliverables": ["Configuração validada e encerramento por sinal.", "Logs estruturados, health checks e métricas.", "Pipeline de testes e artefato reproduzível."], "rubric": ["Nenhum segredo no repositório.", "Timeouts e shutdown são testáveis.", "Procedimento de deploy e rollback está documentado."]}, {"id": 12, "title": "Engenharia e especialização", "tag": "Especialista", "summary": "Integre o aprendizado e saiba investigar além da API pública.", "skills": ["AST e toolchain", "Sistemas distribuídos", "Projeto final"], "project": "Central de serviços — projeto final", "deliverables": ["API com ordens, evidências, confirmação e fechamento.", "Banco, autorização, outbox e worker cancelável.", "Testes, perfis, documentação e demonstração de falhas."], "rubric": ["Fluxo completo funciona com evidências verificáveis.", "Nenhuma baixa ou despesa é duplicada por repetição.", "Defende decisões e limitações com clareza."]}], "lessons": [{"id": 1, "level": 1, "week": 1, "title": "Seu primeiro programa em Go", "goal": "Executar um programa e explicar package, import e main.", "theory": [{"title": "Um programa é uma sequência de instruções", "text": "O código-fonte é texto escrito por você. O compilador verifica esse texto e o transforma em um executável. No começo, pense em entrada → processamento → saída. Nosso primeiro programa só produz uma saída no terminal."}, {"title": "As três peças do primeiro arquivo", "text": "package main identifica o pacote que pode formar um programa executável. import \"fmt\" disponibiliza ferramentas de formatação e impressão. func main() é o ponto de entrada desse programa. As chaves delimitam as instruções da função; fmt.Println escreve uma linha."}, {"title": "Prepare sua oficina", "text": "No Windows, instale a versão estável pelo instalador oficial em go.dev/dl e reabra o terminal. Confira com go version. Crie uma pasta go-forge, entre nela e execute go mod init example.com/estudos. Salve o código em main.go e rode go run .; para gerar um executável, use go build .. No Playground, basta colar o programa completo e clicar em Run. Um erro do compilador é uma pista: leia o arquivo, a linha e a mensagem antes de mudar o código."}], "code": "package main\n\nimport \"fmt\"\n\nfunc main() {\n    fmt.Println(\"Olá, Go!\")\n}\n", "expected": "Olá, Go!", "quiz": {"question": "Qual é o ponto de entrada de um programa executável Go?", "options": ["import \"fmt\"", "func main()", "fmt.Println", "package fmt"], "answer": 1, "explanation": "O runtime chama main.main. O package main contém o programa; a função main contém as instruções iniciais."}, "exercises": [{"id": 1, "title": "Sua primeira saída", "prompt": "Escreva um programa que imprima duas linhas: “Salve, Alex!” e “Estou aprendendo Go.”. Rode e compare a saída.", "hint": "Faça duas chamadas a fmt.Println dentro de main.", "solution": "Dentro de main: fmt.Println(\"Salve, Alex!\") e fmt.Println(\"Estou aprendendo Go.\"). Mantenha package main e import \"fmt\".", "criteria": ["As duas linhas aparecem na ordem pedida.", "Você executou no terminal ou no Playground."]}, {"id": 2, "title": "Leia o erro", "prompt": "Troque Println por println em fmt.Println. Registre a mensagem e explique por que falhou. Depois corrija.", "hint": "Go diferencia letras maiúsculas de minúsculas; símbolos exportados começam com maiúscula.", "solution": "fmt.println não é uma função exportada do pacote fmt. Restaure fmt.Println. Existe um builtin println, mas ele não é fmt.println e não é nossa ferramenta de saída normal.", "criteria": ["Registra a mensagem observada.", "Explica a diferença entre os identificadores."]}, {"id": 3, "title": "Explique sem copiar", "prompt": "Explique com suas palavras o papel de package main, import e func main. Compare go run . e go build ..", "hint": "Separe a organização do arquivo, a dependência e o ponto de entrada.", "solution": "package main forma o comando; import inclui o pacote usado; main inicia as instruções. go run compila e executa; go build gera o binário no caso de um comando.", "criteria": ["Explica os três elementos.", "Diferencia execução de geração do executável."]}], "source": "https://go.dev/doc/tutorial/getting-started", "caution": "", "local": false, "minutes": 45}, {"id": 2, "level": 1, "week": 2, "title": "Valores, variáveis e tipos", "goal": "Representar dados e prever o resultado de expressões.", "theory": [{"title": "O tipo descreve o valor", "text": "string representa texto, bool representa verdadeiro ou falso, e int representa inteiros. Go tem tipagem estática: a variável tem um tipo definido durante a compilação. Use := para declarar uma variável local com inferência. Atribuir outro valor usa =, sem os dois pontos."}, {"title": "Zero também é um estado", "text": "var quantidade int começa em zero. bool começa em false e string começa vazia. const declara uma constante. Ao calcular dinheiro, represente centavos com inteiros e estabeleça limites; float64 usa aproximações binárias e pode surpreender em operações financeiras."}, {"title": "Faça o cálculo à mão", "text": "A expressão 5/2, com operandos inteiros, resulta em 2. Para uma razão fracionária, converta antes de dividir: float64(5)/2. fmt.Printf aceita verbos como %s para string e %d para inteiro. Variáveis locais declaradas e não utilizadas causam erro; isso ajuda a manter o programa claro."}], "code": "package main\nimport \"fmt\"\nfunc main() {\n    nome := \"Alex\"\n    horasPorSemana := 8\n    const semanas = 36\n    fmt.Printf(\"%s: %d horas de prática\\n\", nome, horasPorSemana*semanas)\n}\n", "expected": "Alex: 288 horas de prática", "quiz": {"question": "Quanto vale 5 / 2 quando ambos os operandos são inteiros?", "options": ["2.5", "3", "2", "Erro de compilação"], "answer": 2, "explanation": "Divisão entre inteiros descarta a parte fracionária em direção a zero. A conversão deve acontecer antes da divisão."}, "exercises": [{"id": 1, "title": "Calculadora de estudo", "prompt": "Use uma variável com 6 horas semanais e outra com 4 semanas. Imprima o total de horas do mês e o tipo do total.", "hint": "Use multiplicação e o verbo %T em fmt.Printf.", "solution": "total := horas * semanas; fmt.Printf(\"%d horas (%T)\\n\", total, total). Para 6 e 4, a saída é 24 horas (int).", "criteria": ["Usa variáveis.", "O total é 24 e o tipo é int."]}, {"id": 2, "title": "Dinheiro sem surpresa", "prompt": "Um serviço custa 12550 centavos. Calcule o total de três serviços e mostre reais e centavos.", "hint": "Parte inteira: total/100. Centavos: total%100. Formate com %02d.", "solution": "O total é 37650 centavos; fmt.Printf(\"R$ %d,%02d\\n\", total/100, total%100) produz R$ 376,50.", "criteria": ["Mantém o cálculo em inteiros.", "Formata duas casas de centavos."]}, {"id": 3, "title": "Três valores zero", "prompt": "Declare int, string e bool sem atribuição. Mostre os três e explique seus valores iniciais.", "hint": "var nome tipo não exige um valor explícito.", "solution": "var n int; var s string; var ok bool. Os valores são 0, \"\" e false. Para visualizar a string vazia, use %q.", "criteria": ["Demonstra os três tipos.", "Explica zero value."]}], "source": "https://go.dev/tour/basics/8", "caution": "", "local": false, "minutes": 45}, {"id": 3, "level": 1, "week": 3, "title": "Decisões, laços e decomposição", "goal": "Transformar uma regra simples em controle de fluxo.", "theory": [{"title": "Deixe a regra visível", "text": "if executa um bloco quando a condição é verdadeira; else trata a alternativa. Expressões lógicas usam &&, || e !. switch é útil para alternativas de um mesmo valor. A abertura da chave fica na mesma linha da condição, conforme o estilo normal de Go."}, {"title": "Um único laço, muitas formas", "text": "for cobre repetição com contador, com condição ou sem condição. break interrompe o laço, continue avança à próxima iteração. Antes de rodar, escreva a primeira e a última iteração no papel: esse hábito evita erros de limite."}, {"title": "Pense em casos de fronteira", "text": "Uma regra que aprova valor >= 100 deve ser verificada com 99, 100 e 101. Separe regras em passos pequenos: ler ou definir o dado, validar, calcular e imprimir. A clareza importa mais do que reduzir o número de linhas."}], "code": "package main\nimport \"fmt\"\nfunc main() {\n    for numero := 1; numero <= 5; numero++ {\n        if numero%2 == 0 {\n            fmt.Println(numero, \"par\")\n        } else {\n            fmt.Println(numero, \"ímpar\")\n        }\n    }\n}\n", "expected": "1 ímpar\n2 par\n3 ímpar\n4 par\n5 ímpar", "quiz": {"question": "Quantas vezes roda for i := 0; i < 3; i++?", "options": ["2", "3", "4", "Até ocorrer break"], "answer": 1, "explanation": "O corpo roda para i igual a 0, 1 e 2. Em i igual a 3 a condição já é falsa."}, "exercises": [{"id": 1, "title": "Situação do estoque", "prompt": "Para estoque negativo, imprima “inválido”; zero, “esgotado”; 1 a 5, “baixo”; acima disso, “normal”.", "hint": "Teste o negativo antes das outras faixas.", "solution": "Uma cadeia if n < 0 / else if n == 0 / else if n <= 5 / else cobre as faixas sem sobreposição.", "criteria": ["Verifica -1, 0, 1, 5 e 6.", "Cada valor recebe uma única situação."]}, {"id": 2, "title": "Acumulador", "prompt": "Some todos os números pares de 1 a 10 usando for.", "hint": "Comece com soma := 0 e acrescente i quando i%2 == 0.", "solution": "A soma é 30: 2 + 4 + 6 + 8 + 10. O laço deve incluir o 10.", "criteria": ["Resultado igual a 30.", "Limites incluem 1 e 10."]}, {"id": 3, "title": "Rastreie uma execução", "prompt": "Descreva o valor de soma depois de cada iteração do exercício anterior, incluindo as ímpares.", "hint": "Uma iteração ímpar não muda o acumulador.", "solution": "Após i de 1 a 10: 0, 2, 2, 6, 6, 12, 12, 20, 20, 30.", "criteria": ["Apresenta dez estados.", "Explica por que alguns valores se repetem."]}], "source": "https://go.dev/tour/flowcontrol/1", "caution": "", "local": false, "minutes": 45}, {"id": 4, "level": 2, "week": 4, "title": "Funções e múltiplos retornos", "goal": "Extrair regras para funções previsíveis.", "theory": [{"title": "Um contrato pequeno", "text": "Uma função tem nome, parâmetros, tipos de retorno e corpo. Procure nomes que revelem a intenção: calcularTotal é mais claro do que processar. Valores são passados por cópia; a cópia de um slice ainda referencia seu array subjacente, tema da próxima aula."}, {"title": "Mais de um resultado", "text": "Go permite múltiplos retornos. Uma função pode devolver (int, bool), onde o bool indica se o cálculo faz sentido. Em operações que podem falhar com uma causa útil, adotaremos (valor, error) nos próximos níveis. Retornos antecipados reduzem a profundidade de ifs."}, {"title": "Escopo e efeitos", "text": "Variáveis locais só existem dentro de seu escopo. Evite alterar variáveis globais para devolver resultados. Funções que dependem apenas dos parâmetros e retornam um resultado são fáceis de prever e testar. Não ignore um resultado importante usando _ sem explicar a decisão."}], "code": "package main\nimport \"fmt\"\nfunc total(valor, quantidade int) (int, bool) {\n    if valor < 0 || quantidade < 0 { return 0, false }\n    return valor * quantidade, true\n}\nfunc main() {\n    resultado, ok := total(1250, 3)\n    fmt.Println(resultado, ok)\n}\n", "expected": "3750 true", "quiz": {"question": "O que return 0, false faz no exemplo?", "options": ["Encerra só o if", "Encerra a função e devolve dois resultados", "Encerra todo o programa", "Lança uma exceção"], "answer": 1, "explanation": "return encerra a função atual. Quem chamou recebe os dois resultados e decide o próximo passo."}, "exercises": [{"id": 1, "title": "Desconto com contrato", "prompt": "Crie desconto(valor, percentual int) (int, bool), com percentual entre 0 e 100 e valor não negativo. Retorne o valor final em centavos.", "hint": "Valide primeiro e documente o arredondamento inteiro.", "solution": "Rejeite valor < 0, percentual < 0 ou > 100. Calcule valor - valor*percentual/100, declarando que a divisão inteira trunca a parcela do desconto. Assuma valores pequenos para evitar overflow.", "criteria": ["Testa 0%, 100% e percentual inválido.", "Documenta o arredondamento."]}, {"id": 2, "title": "Faça a previsão", "prompt": "Sem executar, preveja total(100, 0), total(-1, 2) e total(100, 2). Depois confira.", "hint": "A validação ocorre antes da multiplicação.", "solution": "Resultados: (0, true), (0, false) e (200, true). Zero quantidade é aceito neste contrato.", "criteria": ["Acerta os três pares.", "Diferencia zero válido de entrada inválida."]}, {"id": 3, "title": "Uma função por regra", "prompt": "Extraia do projeto do nível anterior uma função que classifica o estoque e devolve string.", "hint": "A função não precisa imprimir: main pode imprimir o retorno.", "solution": "func classificar(n int) string com retornos antecipados para as faixas. Manter a saída no main separa cálculo de apresentação.", "criteria": ["A regra não usa fmt.", "O chamador decide como mostrar a situação."]}], "source": "https://go.dev/tour/basics/4", "caution": "", "local": false, "minutes": 45}, {"id": 5, "level": 2, "week": 5, "title": "Arrays, slices e maps", "goal": "Escolher a coleção certa e reconhecer compartilhamento de dados.", "theory": [{"title": "Array e slice têm papéis distintos", "text": "Um array tem tamanho no tipo, como [3]int. Um slice descreve uma janela de um array: possui comprimento e capacidade. append devolve um slice atualizado e pode alocar outro array. Sempre guarde seu retorno; não presuma que uma alteração por um slice fique isolada dos outros."}, {"title": "Map é associação, não sequência", "text": "map[string]int associa chaves a valores. A consulta v, ok := m[chave] distingue uma ausência de um zero armazenado. make inicializa um map para escrita. Ler de um map nil funciona; escrever nele causa panic. A ordem de iteração não é garantida."}, {"title": "Copiar intencionalmente", "text": "Para uma cópia independente de elementos int, use append([]int(nil), original...) ou slices.Clone. Em elementos que contêm ponteiros, maps ou slices, a cópia ainda é superficial. Para gerar relatórios ordenados a partir de maps, ordene as chaves explicitamente."}], "code": "package main\nimport \"fmt\"\nfunc main() {\n    precos := []int{1000, 2000}\n    precos = append(precos, 1500)\n    total := 0\n    for _, preco := range precos { total += preco }\n    estoque := map[string]int{\"TAG\": 4}\n    n, existe := estoque[\"TAG\"]\n    fmt.Println(total, n, existe)\n}\n", "expected": "4500 4 true", "quiz": {"question": "A ordem de iteração de um map é garantida?", "options": ["Sim, por inserção", "Sim, em ordem alfabética", "Não", "Somente para string"], "answer": 2, "explanation": "Não dependa da ordem de maps. Ordene uma lista de chaves quando a ordem for um requisito."}, "exercises": [{"id": 1, "title": "Agrupe por categoria", "prompt": "Dadas as categorias TAG, GPS, TAG, crie um map com a contagem de cada uma.", "hint": "Inicialize map[string]int e incremente contagem[categoria].", "solution": "O resultado lógico é TAG: 2 e GPS: 1. A ordem em que forem impressos não é um critério.", "criteria": ["Conta repetições.", "Não depende da ordem do map."]}, {"id": 2, "title": "Cópia ou janela?", "prompt": "Crie a := []int{1, 2, 3}; b := a[:2]; altere b[0]. Explique o efeito em a e repita usando uma cópia.", "hint": "O slicing não copia o array.", "solution": "b[0] também muda a[0]. Com b := append([]int(nil), a[:2]...), o novo array isola a alteração dos inteiros.", "criteria": ["Demonstra o compartilhamento.", "Mostra uma cópia independente."]}, {"id": 3, "title": "Ausência não é zero", "prompt": "Armazene GPS com quantidade 0 e consulte GPS e AUSENTE usando comma-ok.", "hint": "Use quantidade, existe := estoque[chave].", "solution": "GPS retorna (0, true), AUSENTE retorna (0, false). São situações diferentes apesar do mesmo valor numérico.", "criteria": ["Usa o booleano da consulta.", "Diferencia os dois casos."]}], "source": "https://go.dev/tour/moretypes/7", "caution": "", "local": false, "minutes": 45}, {"id": 6, "level": 2, "week": 6, "title": "Strings, runes e entrada de dados", "goal": "Tratar texto UTF-8 sem confundir bytes com caracteres.", "theory": [{"title": "String é uma sequência de bytes", "text": "Strings são imutáveis e podem conter UTF-8. len(texto) mede bytes. range sobre uma string decodifica runes, que representam pontos de código Unicode. Uma letra percebida pelo usuário pode conter mais de um ponto de código: rune também não é sinônimo universal de caractere visual."}, {"title": "Normalize o que for necessário", "text": "strings.TrimSpace remove espaços nas bordas e strings.ToLower ajuda em comparações simples. Isso não resolve todas as regras de equivalência Unicode. Para validar IMEI, trate como string de dígitos, preservando zeros à esquerda; não faça aritmética com identificadores."}, {"title": "Entrada precisa de tratamento de erro", "text": "bufio.Scanner lê tokens, por padrão linhas, e tem limite de tamanho que deve ser ajustado para entradas maiores. strconv.Atoi converte texto para int e devolve erro. Verifique Scanner.Err e falhas de conversão. Os exercícios podem começar com strings fixas antes de usar os.Stdin localmente."}], "code": "package main\nimport (\n    \"fmt\"\n    \"strings\"\n    \"unicode/utf8\"\n)\nfunc main() {\n    nome := strings.TrimSpace(\"  José  \")\n    fmt.Println(nome, len(nome), utf8.RuneCountInString(nome))\n}\n", "expected": "José 5 4", "quiz": {"question": "Por que len(\"José\") vale 5 em UTF-8?", "options": ["Conta o terminador nulo", "é ocupa dois bytes", "Toda letra usa dois bytes", "len conta palavras"], "answer": 1, "explanation": "J, o e s usam um byte cada; é usa dois. São cinco bytes e quatro pontos de código."}, "exercises": [{"id": 1, "title": "Nome aproveitável", "prompt": "Remova espaços nas bordas de um nome e rejeite o resultado vazio. Preserve os acentos.", "hint": "TrimSpace vem antes da comparação com \"\".", "solution": "nome = strings.TrimSpace(nome); if nome == \"\" { ... }. Preservar acentos não exige converter para ASCII.", "criteria": ["Rejeita apenas espaços.", "Mantém José como José."]}, {"id": 2, "title": "IMEI textual", "prompt": "Verifique se um identificador tem exatamente 15 bytes, todos entre 0 e 9. Explique por que isso ainda não valida o dígito verificador.", "hint": "Dígitos ASCII têm um byte cada. Verifique cada posição.", "solution": "len(s) == 15 e um laço que rejeita s[i] < '0' ou s[i] > '9'. Isso valida o formato, não Luhn, existência ou vínculo do aparelho.", "criteria": ["Preserva zeros iniciais.", "Distingue formato de validade completa."]}, {"id": 3, "title": "Bytes e runes", "prompt": "Compare len e RuneCountInString para Go, ação e um emoji de sua escolha. Explique os resultados observados.", "hint": "Os números variam com a codificação e a composição Unicode.", "solution": "Go tem 2 bytes/2 runes; ação tem 6 bytes/4 runes. Para o emoji, registre os resultados reais: emojis compostos podem ter várias runes.", "criteria": ["Registra os resultados.", "Não assume uma rune por símbolo visual."]}], "source": "https://go.dev/blog/strings", "caution": "", "local": false, "minutes": 45}, {"id": 7, "level": 3, "week": 7, "title": "Structs, ponteiros e métodos", "goal": "Agrupar dados e controlar quando uma operação altera o original.", "theory": [{"title": "Dados com significado", "text": "Um struct agrupa campos nomeados. Um tipo definido pode receber métodos. Prefira representar regras por tipos do domínio em vez de passar várias strings sem relação. Campos exportados começam com maiúscula e podem receber tags, como json:\"id\", para orientar bibliotecas."}, {"title": "Ponteiro dá acesso ao mesmo valor", "text": "&x obtém o endereço e *p acessa o valor apontado. Go continua passando tudo por valor: ao passar um ponteiro, a cópia contém o mesmo endereço. Um método com receiver *OS pode alterar a OS original. Um receiver OS recebe uma cópia do struct, que pode ainda conter referências internas."}, {"title": "Mantenha a invariável perto da mudança", "text": "Uma OS concluída pode exigir evidências revisadas. Coloque a validação no método de transição para impedir que um chamador pule a regra por acidente. Nem todo campo precisa ser público. Evite expor mutação irrestrita quando existe uma invariável relevante."}], "code": "package main\nimport \"fmt\"\ntype Ordem struct { ID int; Status string }\nfunc (o *Ordem) Iniciar() { o.Status = \"em execução\" }\nfunc main() {\n    os := Ordem{ID: 1, Status: \"aberta\"}\n    os.Iniciar()\n    fmt.Println(os.ID, os.Status)\n}\n", "expected": "1 em execução", "quiz": {"question": "Por que Iniciar usa receiver *Ordem?", "options": ["Para permitir alterar a ordem original", "Porque métodos sempre exigem ponteiros", "Para criar herança", "Para tornar o código paralelo"], "answer": 0, "explanation": "O ponteiro permite que o método altere os campos da ordem original. Receivers por valor também existem."}, "exercises": [{"id": 1, "title": "Transição controlada", "prompt": "Implemente Concluir() bool, permitindo mudar de “em execução” para “concluída” e recusando os demais estados.", "hint": "Verifique o estado antes de atribuir.", "solution": "Use receiver *Ordem; retorne false sem alterar se Status for diferente de \"em execução\". Caso contrário, atribua \"concluída\" e retorne true.", "criteria": ["Não altera ordem aberta.", "Conclui uma ordem em execução."]}, {"id": 2, "title": "Cópia do struct", "prompt": "Copie uma Ordem para outra variável, altere o ID da cópia e explique por que a original não muda.", "hint": "Os campos do exemplo são int e string, e o struct é copiado.", "solution": "copia := original; copia.ID = 2 altera apenas a cópia. Se houvesse um campo slice, seu array poderia continuar compartilhado.", "criteria": ["Demonstra o comportamento.", "Menciona a cópia superficial."]}, {"id": 3, "title": "Modele equipamento", "prompt": "Defina Equipamento com IMEI textual, Modelo e Ativo. Justifique os tipos.", "hint": "Identificadores não são quantidades.", "solution": "IMEI e Modelo são string; Ativo é bool. O IMEI textual preserva zeros à esquerda.", "criteria": ["Usa IMEI string.", "Explica as escolhas."]}], "source": "https://go.dev/tour/moretypes/2", "caution": "", "local": false, "minutes": 45}, {"id": 8, "level": 3, "week": 8, "title": "Interfaces e composição", "goal": "Depender de comportamentos pequenos em vez de implementações concretas.", "theory": [{"title": "Implementação implícita", "text": "Uma interface descreve um conjunto de métodos. Um tipo a implementa se seu conjunto de métodos satisfizer o contrato, sem uma declaração implements. Comece com uma interface pequena no pacote consumidor. Uma abstração útil corresponde a uma necessidade real de substituição."}, {"title": "Composição com responsabilidade clara", "text": "Go usa composição e embedding em vez de hierarquia de classes. io.Reader e io.Writer são exemplos de interfaces pequenas que se combinam. Faça a regra de negócio depender da operação que precisa, não de todos os detalhes de um banco."}, {"title": "A armadilha do nil", "text": "Uma interface tem tipo dinâmico e valor dinâmico. Uma interface que contém um ponteiro nil de um tipo concreto não é igual a nil. Devolver explicitamente nil em caminhos sem erro evita um erro comum em funções que retornam error. Prefira composição simples antes de factories e camadas extras."}], "code": "package main\nimport \"fmt\"\ntype Notificador interface { Avisar(string) }\ntype Console struct{}\nfunc (Console) Avisar(s string) { fmt.Println(\"aviso:\", s) }\nfunc concluir(n Notificador) { n.Avisar(\"OS concluída\") }\nfunc main() { concluir(Console{}) }\n", "expected": "aviso: OS concluída", "quiz": {"question": "Quando um tipo implementa uma interface em Go?", "options": ["Após usar implements", "Quando satisfaz o conjunto de métodos exigido", "Somente se estiver no mesmo arquivo", "Somente quando usa embedding"], "answer": 1, "explanation": "A satisfação da interface é implícita. Assinaturas e conjunto de métodos precisam corresponder."}, "exercises": [{"id": 1, "title": "Um segundo notificador", "prompt": "Implemente um notificador que acumule mensagens em um slice e passe-o a concluir.", "hint": "Use um ponteiro se o método acrescentar ao slice do receptor.", "solution": "type Memoria struct { Mensagens []string }; func (m *Memoria) Avisar(s string) { m.Mensagens = append(m.Mensagens, s) }. Use concluir(&m).", "criteria": ["Funciona sem mudar concluir.", "Preserva a mensagem para inspeção."]}, {"id": 2, "title": "Interface mínima", "prompt": "Desenhe uma interface para uma regra que só precisa buscar uma ordem por ID. Quais métodos devem ficar de fora?", "hint": "O consumidor só precisa de uma capacidade.", "solution": "Uma opção é Buscar(ctx context.Context, id int64) (Ordem, error). Listar, Salvar e Excluir ficam de fora se essa regra não os usa.", "criteria": ["Mantém o contrato pequeno.", "Justifica o contexto e o erro."]}, {"id": 3, "title": "Nil tipado", "prompt": "Preveja: var p *Console; var n Notificador = p; n == nil. Explique sem chamar o método.", "hint": "A interface guarda um tipo dinâmico, mesmo que o valor seja nil.", "solution": "A comparação é false. n contém o tipo *Console e um ponteiro nil; não é uma interface sem tipo e sem valor.", "criteria": ["Prevê false.", "Explica tipo e valor dinâmicos."]}], "source": "https://go.dev/tour/methods/9", "caution": "", "local": false, "minutes": 45}, {"id": 9, "level": 3, "week": 9, "title": "Erros como parte do contrato", "goal": "Tratar falhas esperadas e preservar a causa com wrapping.", "theory": [{"title": "Erro é um valor", "text": "O tipo error é uma interface com Error() string. O padrão (valor, error) torna falhas parte explícita da assinatura. Verifique err antes de usar o valor, acrescente contexto útil e devolva ao chamador que pode decidir o que fazer."}, {"title": "Classifique sem comparar texto", "text": "Use errors.Is para reconhecer sentinelas na cadeia e errors.As para extrair um tipo de erro. fmt.Errorf com %w preserva a causa. Comparar err.Error() com uma mensagem torna o código frágil a alterações de texto e traduções."}, {"title": "Panic não é a validação de formulário", "text": "Panic costuma indicar uma situação que viola pressupostos ou um erro de programação. Reserve recover para fronteiras em que a política seja explícita. Use defer para liberar recursos, mas registre a limpeza apenas depois de confirmar que o recurso foi adquirido. Evite registrar a mesma falha em todas as camadas."}], "code": "package main\nimport (\n    \"errors\"\n    \"fmt\"\n)\nvar ErrInvalida = errors.New(\"ordem inválida\")\nfunc validar(id int) error {\n    if id <= 0 { return fmt.Errorf(\"id %d: %w\", id, ErrInvalida) }\n    return nil\n}\nfunc main() { fmt.Println(errors.Is(validar(0), ErrInvalida)) }\n", "expected": "true", "quiz": {"question": "Qual verbo de fmt.Errorf preserva a causa para errors.Is?", "options": ["%s", "%v", "%w", "%d"], "answer": 2, "explanation": "%w faz wrapping do erro. A mensagem ganha contexto e a cadeia continua inspecionável."}, "exercises": [{"id": 1, "title": "Validação com causa", "prompt": "Crie ErrIMEIInvalido e uma função que devolva esse erro com contexto quando o formato for inválido.", "hint": "Reutilize o validador textual e fmt.Errorf com %w.", "solution": "Declare uma sentinela com errors.New. Ao falhar, retorne fmt.Errorf(\"validar equipamento: %w\", ErrIMEIInvalido). Não exponha identificadores sensíveis no log.", "criteria": ["errors.Is reconhece a causa.", "Entradas válidas retornam nil."]}, {"id": 2, "title": "Não engula erro", "prompt": "Revise uma chamada resultado, _ := operacao(). Explique quando ignorar o erro seria aceitável e quando destrói a informação necessária.", "hint": "A decisão depende do contrato e das consequências.", "solution": "Se a operação pode falhar e o valor deixa de ser confiável, verifique o erro e propague ou trate. Ignorar só é defensável com uma razão explícita e uma alternativa segura.", "criteria": ["Apresenta uma decisão contextual.", "Não usa panic como resposta automática."]}, {"id": 3, "title": "A ordem do defer", "prompt": "Explique por que f, err := os.Open(...); defer f.Close(); if err != nil { ... } está errado e reordene.", "hint": "Se Open falhar, f não é um recurso válido.", "solution": "Verifique err e retorne primeiro. Só então faça defer f.Close(). Para escrita crítica, também é necessário tratar erros de flush/Close conforme o contrato.", "criteria": ["Coloca o defer após a verificação.", "Reconhece falha possível na finalização."]}], "source": "https://go.dev/blog/go1.13-errors", "caution": "", "local": false, "minutes": 45}, {"id": 10, "level": 4, "week": 10, "title": "Módulos, pacotes e documentação", "goal": "Organizar um projeto sem criar dependências cíclicas.", "theory": [{"title": "Módulo não é pacote", "text": "Um módulo é uma unidade de versionamento descrita por go.mod. Um pacote é um conjunto de arquivos Go de um diretório, com regras para arquivos de teste e build. O caminho de importação inclui o módulo e o subdiretório. O nome do pacote costuma ser curto e expressar sua finalidade."}, {"title": "Ferramentas do dia a dia", "text": "go mod init inicia um módulo; go mod tidy alinha dependências; go fmt ./... formata; go test ./... testa; go vet ./... procura problemas suspeitos. go.sum registra checksums de conteúdo de módulos, não uma lista de segredos nem um lockfile tradicional."}, {"title": "Comece pequeno", "text": "Separe um comando em cmd quando houver motivo e use internal para limitar importações externas à árvore permitida. Evite pacotes util ou common que concentrem responsabilidades sem relação. Comentários de símbolos exportados explicam intenção e contratos; go doc permite consultá-los."}], "code": "package main\nimport \"fmt\"\n// Total soma valores em centavos. A entrada não é modificada.\nfunc Total(valores []int) int {\n    n := 0\n    for _, v := range valores { n += v }\n    return n\n}\nfunc main() { fmt.Println(Total([]int{100, 200})) }\n", "expected": "300", "quiz": {"question": "O que go.mod descreve principalmente?", "options": ["Uma instância de banco", "O módulo e suas dependências/requisitos", "Uma única função", "Os valores de variáveis de ambiente"], "answer": 1, "explanation": "go.mod identifica o módulo, a versão mínima da linguagem e requisitos de dependências, entre outras diretivas."}, "exercises": [{"id": 1, "title": "Dois pacotes", "prompt": "Crie um módulo example.com/oficina com pacote internal/ordem e um comando que importe uma função dele.", "hint": "O nome importado combina módulo e diretório.", "solution": "Crie internal/ordem/ordem.go com package ordem e função exportada. Importe \"example.com/oficina/internal/ordem\" no comando e execute go run ..", "criteria": ["Não há ciclos.", "O comando executa a função importada."]}, {"id": 2, "title": "Documente o contrato", "prompt": "Documente uma função de soma, incluindo unidade, mutação e entradas aceitas.", "hint": "Escreva o que o usuário da função precisa saber.", "solution": "Declare que recebe centavos, se aceita negativos, se altera a entrada e como trata slice vazio. O comentário deve concordar com a implementação.", "criteria": ["Explicita unidade e limites.", "Não repete apenas o nome."]}, {"id": 3, "title": "Checklist de ferramentas", "prompt": "Execute go fmt ./..., go vet ./... e go test ./... no seu módulo. Anote os resultados reais.", "hint": "Sem testes, o comando ainda pode informar [no test files].", "solution": "Registre saídas reais e corrija os problemas reportados. [no test files] não significa que a regra foi testada.", "criteria": ["Registra execução real.", "Diferencia ausência de testes de testes aprovados."]}], "source": "https://go.dev/doc/tutorial/create-module", "caution": "", "local": true, "minutes": 45}, {"id": 11, "level": 4, "week": 11, "title": "I/O, arquivos e composição", "goal": "Processar fluxos usando Reader e Writer.", "theory": [{"title": "Um protocolo comum", "text": "io.Reader expõe Read e io.Writer expõe Write. Muitas fontes e destinos implementam essas interfaces: arquivos, buffers, conexões e leitores de string. Escrever uma função que recebe io.Reader permite testar sem criar um arquivo real."}, {"title": "Leituras podem ser parciais", "text": "Read pode devolver n > 0 junto de um erro. Processe os bytes válidos antes de interpretar o erro. io.EOF sinaliza fim do fluxo; não é sempre um fracasso do negócio. io.Copy implementa a cópia e você deve verificar o erro que ele retorna."}, {"title": "Recursos e limites", "text": "Abra um arquivo, verifique o erro e só então agende o fechamento. Evite io.ReadAll sem limite para entradas não confiáveis. io.LimitReader limita bytes lidos, mas você precisa de uma política explícita para detectar que a entrada excedeu o máximo em vez de aceitar truncamento silencioso."}], "code": "package main\nimport (\n    \"bytes\"\n    \"fmt\"\n    \"io\"\n    \"strings\"\n)\nfunc main() {\n    var destino bytes.Buffer\n    n, err := io.Copy(&destino, strings.NewReader(\"OS-001\"))\n    if err != nil { fmt.Println(err); return }\n    fmt.Println(n, destino.String())\n}\n", "expected": "6 OS-001", "quiz": {"question": "Read devolveu n > 0 e io.EOF. O que fazer primeiro?", "options": ["Descartar o buffer", "Processar os n bytes válidos", "Chamar panic", "Fechar o processo"], "answer": 1, "explanation": "Os bytes retornados são válidos mesmo quando há um erro junto. Depois de processá-los, trate EOF ou outro erro."}, "exercises": [{"id": 1, "title": "Transformação testável", "prompt": "Escreva copiar(dst io.Writer, src io.Reader) error sem depender de os.File.", "hint": "io.Copy já conhece os dois protocolos.", "solution": "_, err := io.Copy(dst, src); return err. Um buffer de memória permite observar a saída em testes.", "criteria": ["Aceita buffers e arquivos.", "Propaga o erro de cópia."]}, {"id": 2, "title": "Entrada limitada", "prompt": "Projete uma leitura de no máximo 1024 bytes que rejeite entradas maiores, sem truncá-las silenciosamente.", "hint": "Leia até limite+1 e confira o tamanho.", "solution": "Use io.LimitReader(r, 1025), io.ReadAll, trate o erro e rejeite len(b) > 1024. Só então aceite o conteúdo.", "criteria": ["Detecta 1025 bytes.", "Não aceita truncamento como sucesso."]}, {"id": 3, "title": "Caminhos de falha", "prompt": "Liste erros possíveis ao exportar dados para um arquivo e como comunicá-los.", "hint": "Criar, escrever, sincronizar e fechar são operações distintas.", "solution": "Considere permissão, diretório ausente, disco cheio e erro ao fechar. Acrescente contexto com %w e não informe sucesso antes da finalização exigida pelo contrato.", "criteria": ["Cobre criação e escrita.", "Considera o fechamento."]}], "source": "https://pkg.go.dev/io", "caution": "", "local": false, "minutes": 45}, {"id": 12, "level": 4, "week": 12, "title": "JSON, tempo e comandos CLI", "goal": "Criar fronteiras de entrada e saída previsíveis.", "theory": [{"title": "JSON tem regras próprias", "text": "encoding/json usa campos exportados e tags para mapear nomes. json.Marshal cria bytes; Encoder escreve em um fluxo. Ao receber JSON não confiável, limite o corpo, trate falhas e decida se campos desconhecidos e múltiplos valores no mesmo corpo serão aceitos."}, {"title": "Data não é só string", "text": "time.Time representa um instante, com detalhes de localização e leitura monotônica em alguns contextos. RFC3339 é uma boa escolha para intercâmbio de instantes. A formatação de Go usa a data de referência 2006-01-02 15:04:05; datas de negócio precisam de fuso explicitamente definido."}, {"title": "CLI comunica por contrato", "text": "flag fornece flags simples. stdout deve transportar o resultado e stderr os diagnósticos quando o comando for usado em pipelines. Retorne erros de uma função run e decida o código de saída em main. os.Exit não executa defers, por isso deixe recursos fecharem antes de chamá-lo."}], "code": "package main\nimport (\n    \"encoding/json\"\n    \"fmt\"\n)\ntype Ordem struct {\n    ID int `json:\"id\"`\n    Status string `json:\"status\"`\n}\nfunc main() {\n    b, err := json.Marshal(Ordem{ID: 7, Status: \"aberta\"})\n    if err != nil { fmt.Println(err); return }\n    fmt.Println(string(b))\n}\n", "expected": "{\"id\":7,\"status\":\"aberta\"}", "quiz": {"question": "Qual campo encoding/json normalmente serializa?", "options": ["Um campo exportado", "Qualquer campo privado", "Só campos int", "Somente campos com tag obrigatória"], "answer": 0, "explanation": "Campos exportados podem ser serializados; as tags personalizam os nomes e opções, mas não tornam campos privados exportados."}, "exercises": [{"id": 1, "title": "Exportação da OS", "prompt": "Adicione Tecnico e ValorCentavos ao struct e produza JSON com nomes tecnico e valor_centavos.", "hint": "Campos começam com maiúscula; tags controlam o JSON.", "solution": "Tecnico string `json:\"tecnico\"` e ValorCentavos int `json:\"valor_centavos\"`. Verifique o erro do Marshal.", "criteria": ["Saída JSON válida.", "Valor monetário mantém a unidade."]}, {"id": 2, "title": "Data com fuso", "prompt": "Formate um instante conhecido em RFC3339 e explique por que 22/10/2026 10:00 sem fuso é ambíguo.", "hint": "Um horário de parede não identifica sozinho um instante global.", "solution": "Use t.Format(time.RFC3339). Um offset ou localização é necessário para interpretar 10:00 em uma região; não use o fuso do servidor implicitamente.", "criteria": ["Inclui offset ou Z.", "Explica a ambiguidade."]}, {"id": 3, "title": "Contrato de CLI", "prompt": "Desenhe uma flag -status e descreva stdout, stderr e código de saída quando o filtro for inválido.", "hint": "Considere uma pessoa e outro programa consumindo a saída.", "solution": "Dados válidos vão para stdout, erro para stderr e saída não zero indica falha. Documente os valores aceitos e não misture logs ao JSON.", "criteria": ["Define valores aceitos.", "Separa dados e diagnóstico."]}], "source": "https://pkg.go.dev/encoding/json", "caution": "", "local": false, "minutes": 45}, {"id": 13, "level": 5, "week": 13, "title": "Testes unitários e casos de fronteira", "goal": "Escrever um teste que falhe pela razão certa.", "theory": [{"title": "O contrato é o alvo", "text": "Arquivos terminados em _test.go podem definir funções TestXxx(t *testing.T). Organize o teste em preparação, ação e verificação. Primeiro veja o teste falhar, depois implemente a regra e confirme que ele passa. Um teste que nunca falhou pode estar verificando a coisa errada."}, {"title": "Mensagens que ajudam", "text": "Use t.Fatalf quando continuar tornaria o restante do teste inválido; t.Errorf permite registrar a falha e seguir. Mostre entrada, resultado obtido e esperado. Testes no pacote nome_test exercitam a API pública; testes no mesmo pacote também podem acessar detalhes privados, quando necessário."}, {"title": "Fronteiras importam", "text": "Para dinheiro, teste zero, valor mínimo, arredondamento e entradas rejeitadas. Cobertura revela linhas executadas, não garante asserções úteis. Não escreva testes que apenas repetem a mesma fórmula da implementação: use exemplos de negócio calculados de forma independente."}], "code": "package main\nimport \"testing\"\nfunc total(valor, quantidade int) int { return valor * quantidade }\nfunc TestTotal(t *testing.T) {\n    got := total(1250, 3)\n    if got != 3750 { t.Fatalf(\"total = %d; esperado 3750\", got) }\n}\n", "expected": "Em main_test.go: go test -v . → TestTotal deve passar.", "quiz": {"question": "O que a cobertura de linhas comprova?", "options": ["Que todos os contratos estão corretos", "Quais linhas foram executadas nos testes", "Que não existem races", "Que o sistema é seguro"], "answer": 1, "explanation": "Cobertura mostra execução de linhas. Uma linha executada pode continuar contendo erro que nenhuma asserção detectou."}, "exercises": [{"id": 1, "title": "Uma regressão financeira", "prompt": "Teste uma função de desconto com exemplos para 0%, 10% e 100%, e a política para percentual inválido.", "hint": "Defina o resultado esperado antes de implementar.", "solution": "Para 10000 centavos: 0% → 10000, 10% → 9000, 100% → 0. O teste de percentual inválido deve exigir erro ou bool false conforme seu contrato.", "criteria": ["Testa limites.", "Quebrar a validação faz um teste falhar."]}, {"id": 2, "title": "Faça falhar", "prompt": "Altere deliberadamente o resultado esperado de um teste e registre a falha. Depois restaure.", "hint": "A mensagem deve permitir entender entrada, obtido e esperado.", "solution": "Um teste com esperado incorreto deve falhar de modo claro. Se continuar passando, confira se ele é descoberto pelo go test e se a asserção é alcançada.", "criteria": ["Observa falha real.", "Restaura o teste correto."]}, {"id": 3, "title": "Cobertura com julgamento", "prompt": "Execute go test -cover ./... e identifique um comportamento importante que o percentual não prova.", "hint": "Pense em valores, não apenas em linhas.", "solution": "Uma função pode ter 100% de linhas cobertas e não testar overflow, arredondamento ou isolamento entre usuários.", "criteria": ["Registra o resultado real.", "Nomeia uma lacuna concreta."]}], "source": "https://go.dev/doc/tutorial/add-a-test", "caution": "", "local": true, "minutes": 60}, {"id": 14, "level": 5, "week": 14, "title": "Tabelas, subtestes e fronteiras HTTP", "goal": "Escalar verificações sem esconder o comportamento.", "theory": [{"title": "Uma tabela de cenários", "text": "Table-driven tests expressam entradas e expectativas em uma coleção. Cada cenário deve ter um nome que conte a regra. t.Run organiza a saída e permite selecionar um caso com go test -run. Evite uma abstração de teste mais complexa que o próprio comportamento."}, {"title": "Substitua a fronteira", "text": "Injete uma interface pequena, uma função de relógio ou um io.Reader em vez de depender de serviços reais. Um fake em memória registra efeitos observáveis sem reproduzir todos os detalhes da dependência. Um teste de integração complementa o fake verificando o sistema real quando essa fronteira importa."}, {"title": "HTTP sem porta fixa", "text": "net/http/httptest tem ResponseRecorder e NewRequest para testar handlers diretamente, e NewServer para exercitar um cliente contra um servidor de teste. Verifique status, headers e corpo. Não use time.Sleep para coordenar algo que pode ser sinalizado explicitamente."}], "code": "package main\nimport (\n    \"net/http\"\n    \"net/http/httptest\"\n    \"testing\"\n)\nfunc TestHealth(t *testing.T) {\n    h := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n        w.WriteHeader(http.StatusNoContent)\n    })\n    rr := httptest.NewRecorder()\n    h.ServeHTTP(rr, httptest.NewRequest(\"GET\", \"/healthz\", nil))\n    if rr.Code != 204 { t.Fatalf(\"status = %d; esperado 204\", rr.Code) }\n}\n", "expected": "Em main_test.go: go test -v . → TestHealth deve passar.", "quiz": {"question": "Qual ferramenta testa um handler sem abrir uma porta?", "options": ["http.ListenAndServe", "httptest.ResponseRecorder com NewRequest", "time.Sleep", "Um banco em produção"], "answer": 1, "explanation": "O recorder implementa ResponseWriter e registra a resposta gerada pelo handler."}, "exercises": [{"id": 1, "title": "Tabela de estados", "prompt": "Crie subtestes para concluir uma OS aberta, em execução e já concluída.", "hint": "O nome de cada caso deve explicar se a operação é aceita.", "solution": "Apenas o estado em execução deve concluir no contrato anterior; os outros casos recusam sem mutação. Use t.Run para cada cenário.", "criteria": ["Verifica retorno e estado final.", "Casos têm nomes úteis."]}, {"id": 2, "title": "Contrato HTTP", "prompt": "Amplie TestHealth para verificar um header Content-Type em um handler JSON e um corpo válido.", "hint": "Configure headers antes de escrever a resposta.", "solution": "Verifique rr.Header().Get(\"Content-Type\"), rr.Code e decodifique o corpo com json.Decoder. Não compare só uma substring que poderia existir numa resposta de erro.", "criteria": ["Confere status, header e corpo.", "Trata o erro da decodificação."]}, {"id": 3, "title": "Relógio sob controle", "prompt": "Explique como testar uma regra de vencimento sem depender da data de hoje.", "hint": "Passe agora como parâmetro ou injete func() time.Time.", "solution": "Use instantes fixos antes, no limite e depois do vencimento. O resultado precisa ser igual em qualquer dia de execução.", "criteria": ["Usa instantes fixos.", "Testa a fronteira exata."]}], "source": "https://pkg.go.dev/net/http/httptest", "caution": "", "local": true, "minutes": 60}, {"id": 15, "level": 5, "week": 15, "title": "Fuzzing, benchmarks e testes concorrentes", "goal": "Explorar propriedades e separar correção de desempenho.", "theory": [{"title": "Exemplos e propriedades", "text": "Fuzzing gera entradas para encontrar falhas além dos exemplos manuais. Um alvo FuzzXxx recebe *testing.F, registra sementes com Add e chama Fuzz. Escolha uma propriedade verdadeira: um parser não deve causar panic para qualquer entrada, ou um ciclo de serialização deve preservar dados válidos."}, {"title": "Medição exige cuidado", "text": "Benchmarks medem custo de uma operação, enquanto testes verificam correção. Evite incluir preparação que não faz parte do custo pretendido. Repita medições e compare resultados antes de otimizar. O tempo de uma execução no Playground não é um benchmark confiável."}, {"title": "Races são comportamento observado", "text": "go test -race instrumenta acessos e pode detectar data races nos caminhos exercitados. Não demonstra ausência universal de races. Para concorrência determinística, estude também testing/synctest em versões recentes. Sempre execute testes normais e os específicos da concorrência."}], "code": "package main\nimport (\n    \"strings\"\n    \"testing\"\n)\nfunc FuzzTrim(f *testing.F) {\n    f.Add(\"  OS-1 \")\n    f.Fuzz(func(t *testing.T, s string) {\n        once := strings.TrimSpace(s)\n        if strings.TrimSpace(once) != once {\n            t.Fatal(\"TrimSpace deve ser idempotente\")\n        }\n    })\n}\n", "expected": "Em main_test.go: go test -fuzz=FuzzTrim -fuzztime=10s .", "quiz": {"question": "O que go test -race garante?", "options": ["Ausência de qualquer race", "Detecção de races observadas nos caminhos executados", "Maior velocidade", "Correção de deadlocks"], "answer": 1, "explanation": "O detector observa uma execução instrumentada. Caminhos não exercitados podem conter races não detectadas."}, "exercises": [{"id": 1, "title": "Propriedade do validador", "prompt": "Crie um alvo de fuzz para o validador de IMEI que nunca cause panic e só aceite 15 dígitos ASCII.", "hint": "Quando o validador aceitar, confira a propriedade de formato de modo independente.", "solution": "Adicione sementes vazia, válida e com Unicode. Para entradas aceitas, verifique tamanho e bytes; rejeite qualquer aceitação inconsistente.", "criteria": ["Inclui sementes variadas.", "Não depende apenas do mesmo validador na asserção."]}, {"id": 2, "title": "Regressão do fuzz", "prompt": "Explique o que fazer quando o fuzz encontra uma entrada que quebra a função.", "hint": "Não apague a entrada problemática.", "solution": "Reproduza, reduza se necessário, corrija a causa e mantenha o caso no corpus ou como teste de regressão. Verifique o contrato antes de alterar a propriedade.", "criteria": ["Preserva o caso.", "Explica a causa."]}, {"id": 3, "title": "Medição honesta", "prompt": "Desenhe uma comparação entre duas formas de concatenar texto. Liste o que manter igual.", "hint": "Mesma entrada, mesma máquina e mesmo resultado são o começo.", "solution": "Valide a saída, execute benchmarks repetidos com -bench e -benchmem e compare tempo e alocações. Não conclua a partir de uma chamada isolada.", "criteria": ["Mede resultado equivalente.", "Inclui alocações e repetições."]}], "source": "https://go.dev/doc/tutorial/fuzz", "caution": "", "local": true, "minutes": 60}, {"id": 16, "level": 6, "week": 16, "title": "Goroutines e ciclo de vida", "goal": "Iniciar trabalho concorrente e garantir sua finalização.", "theory": [{"title": "Concorrência é organização", "text": "Uma goroutine é uma execução leve gerenciada pelo runtime. go f() inicia f concorrentemente; isso não garante execução paralela naquele instante. Concorrência estrutura atividades que progridem de modo independente. Paralelismo depende também do trabalho, do runtime e dos recursos disponíveis."}, {"title": "Quem espera e quem cancela?", "text": "Quando main retorna, o processo termina sem esperar suas goroutines. sync.WaitGroup acompanha término, mas não transporta erros nem cancela trabalho. O padrão Add antes de iniciar e Done com defer funciona em versões antigas e atuais. Em Go recente existe também WaitGroup.Go; conheça a versão mínima antes de adotá-lo."}, {"title": "Propriedade do ciclo de vida", "text": "Cada goroutine precisa de uma condição de saída. Quem a inicia deve saber como observar seu término e como interrompê-la quando a operação perde o sentido. Dormir por alguns milissegundos para “dar tempo” não cria uma relação confiável de sincronização."}], "code": "package main\nimport (\n    \"fmt\"\n    \"sync\"\n)\nfunc main() {\n    var wg sync.WaitGroup\n    for i := 1; i <= 3; i++ {\n        wg.Add(1)\n        go func(id int) {\n            defer wg.Done()\n            fmt.Println(\"tarefa\", id)\n        }(i)\n    }\n    wg.Wait()\n}\n", "expected": "Três linhas: tarefa 1, tarefa 2 e tarefa 3. A ordem pode variar.", "quiz": {"question": "O que WaitGroup faz?", "options": ["Cancela tarefas automaticamente", "Espera o término das tarefas registradas", "Impede todo acesso concorrente", "Transporta erros"], "answer": 1, "explanation": "WaitGroup sincroniza a espera pelo término. Cancelamento, erros e proteção de dados precisam de mecanismos próprios."}, "exercises": [{"id": 1, "title": "Tarefas com dono", "prompt": "Inicie cinco goroutines e espere todas terminarem sem usar Sleep.", "hint": "Registre cada tarefa antes de iniciá-la.", "solution": "Use WaitGroup com Add(1), defer Done() e Wait() no chamador. A ordem de impressão não é um contrato.", "criteria": ["As cinco terminam antes de main retornar.", "Sem Sleep para sincronizar."]}, {"id": 2, "title": "Resultado compartilhado", "prompt": "Explique por que incrementar um int global em várias goroutines é perigoso e proponha duas soluções.", "hint": "WaitGroup espera, mas não protege o incremento.", "solution": "O incremento é leitura-modificação-escrita e pode ter data race. Proteja com Mutex ou acumule resultados por um canal em uma goroutine dona do total.", "criteria": ["Distingue término de exclusão mútua.", "Propõe duas sincronizações válidas."]}, {"id": 3, "title": "Política de término", "prompt": "Para um leitor em background, descreva como ele recebe cancelamento e quem espera seu encerramento.", "hint": "Pense no caminho feliz e no caminho de erro.", "solution": "O iniciador fornece context, o leitor observa Done nas operações bloqueantes e sinaliza conclusão. O dono cancela e aguarda antes de liberar dependências usadas pela goroutine.", "criteria": ["Há condição de saída.", "Há observação do término."]}], "source": "https://go.dev/tour/concurrency/1", "caution": "", "local": false, "minutes": 60}, {"id": 17, "level": 6, "week": 17, "title": "Channels, select e context", "goal": "Comunicar resultados com cancelamento explícito.", "theory": [{"title": "Transferência e bloqueio", "text": "Um canal sem buffer conecta um envio a um recebimento. Um canal com buffer permite uma quantidade limitada de valores pendentes. Enviar para um canal fechado causa panic. Receber de um canal fechado e drenado devolve o valor zero e ok false; range termina quando o canal fecha e esvazia."}, {"title": "Fechamento tem um dono", "text": "Normalmente quem coordena os produtores fecha o canal quando sabe que não haverá mais envios. Consumidores não fecham o canal só porque pararam de ler. select permite esperar por alternativas, mas não torna uma operação magicamente livre de deadlock. Canais nil bloqueiam seus casos indefinidamente."}, {"title": "Context propaga o fim da operação", "text": "context.Context carrega cancelamento, prazo e valores de escopo da requisição; não é um saco de parâmetros opcionais. Passe-o como primeiro argumento. Chame o cancel de WithCancel ou WithTimeout para liberar recursos. Operações bloqueantes também precisam observar Done ou usar APIs que aceitam o contexto."}], "code": "package main\nimport (\n    \"context\"\n    \"fmt\"\n)\nfunc enviar(ctx context.Context, out chan<- int, v int) error {\n    select {\n    case <-ctx.Done(): return ctx.Err()\n    case out <- v: return nil\n    }\n}\nfunc main() {\n    ctx, cancel := context.WithCancel(context.Background())\n    cancel()\n    fmt.Println(enviar(ctx, make(chan int), 42))\n}\n", "expected": "context canceled", "quiz": {"question": "Quem normalmente fecha um canal de resultados?", "options": ["Qualquer consumidor", "Quem coordena e sabe que todos os envios terminaram", "O garbage collector", "Context automaticamente"], "answer": 1, "explanation": "O fechamento deve acontecer quando não há possibilidade de novos envios, geralmente pelo dono dos produtores."}, "exercises": [{"id": 1, "title": "Cancelamento verificável", "prompt": "Crie um envio bloqueante que termine quando o contexto for cancelado e escreva um teste sem Sleep.", "hint": "Use select entre envio e ctx.Done; sinalize início/término por canais.", "solution": "O cancel faz o caminho de ctx.Done ficar disponível. O teste aguarda a conclusão com prazo apenas como limite de falha e verifica errors.Is(err, context.Canceled).", "criteria": ["Não deixa goroutine bloqueada.", "Verifica o erro de cancelamento."]}, {"id": 2, "title": "Leitura até o fim", "prompt": "Produza os valores 1, 2 e 3 em um canal, feche após os envios e some no consumidor com range.", "hint": "Um produtor único pode fechar com defer close(ch).", "solution": "O consumidor calcula 6 e o range termina após o fechamento. O produtor não envia depois de fechar.", "criteria": ["Resultado 6.", "Fechamento tem um responsável."]}, {"id": 3, "title": "Pronto ao mesmo tempo", "prompt": "Se dois casos de select estiverem prontos, o primeiro no código sempre vence? Explique a implicação para cancelamento.", "hint": "A ordem textual não define prioridade.", "solution": "Não há prioridade pelo primeiro caso. Se trabalho e cancelamento estiverem prontos, o trabalho pode ser escolhido; contratos de cancelamento estrito exigem desenho adicional.", "criteria": ["Não presume prioridade.", "Explica a limitação."]}], "source": "https://go.dev/blog/context", "caution": "", "local": false, "minutes": 60}, {"id": 18, "level": 6, "week": 18, "title": "Mutex, atomics e worker pools", "goal": "Limitar trabalho e proteger invariáveis compartilhadas.", "theory": [{"title": "Proteja a invariável inteira", "text": "sync.Mutex coordena acesso exclusivo. Mantenha a região crítica pequena e não copie um mutex depois que ele for usado. RWMutex só vale a pena se medições e padrão de acesso justificarem. Um map normal não admite leitura e escrita concorrentes sem sincronização."}, {"title": "Contador não é transação", "text": "sync/atomic oferece operações atômicas específicas e úteis para contadores ou protocolos muito bem definidos. Duas variáveis atômicas não tornam uma invariável composta automaticamente atômica. Prefira um mutex quando várias mudanças precisam ocorrer juntas."}, {"title": "Concorrência com limite", "text": "Um worker pool usa uma quantidade fixa de consumidores para processar trabalhos. Limite também fila, memória e tempo. Propague cancelamento em envio, recebimento e operação. O coordenador fecha a fila de entrada após os produtores e fecha resultados depois de todos os workers, sem perder o caminho de erro."}], "code": "package main\nimport (\n    \"fmt\"\n    \"sync\"\n)\ntype Contador struct { mu sync.Mutex; n int }\nfunc (c *Contador) Inc() { c.mu.Lock(); defer c.mu.Unlock(); c.n++ }\nfunc main() {\n    var c Contador\n    var wg sync.WaitGroup\n    for i := 0; i < 100; i++ {\n        wg.Add(1)\n        go func() { defer wg.Done(); c.Inc() }()\n    }\n    wg.Wait()\n    c.mu.Lock(); fmt.Println(c.n); c.mu.Unlock()\n}\n", "expected": "100", "quiz": {"question": "Duas operações atômicas separadas protegem automaticamente uma regra entre dois campos?", "options": ["Sim, sempre", "Não; a invariável composta precisa de um protocolo de sincronização", "Só se forem int64", "Somente em map"], "answer": 1, "explanation": "Atomicidade de cada acesso não torna uma sequência inteira uma transação."}, "exercises": [{"id": 1, "title": "Contador sem race", "prompt": "Extraia Contador e teste 1000 incrementos concorrentes; execute go test -race.", "hint": "A leitura final também precisa respeitar o contrato de sincronização.", "solution": "Espere as tarefas, leia com um método protegido e verifique 1000. O resultado normal sozinho não substitui a análise de sincronização.", "criteria": ["Resultado correto.", "Executa o detector e registra a saída."]}, {"id": 2, "title": "Três workers", "prompt": "Desenhe um pool de três workers para dez ordens, incluindo o encerramento dos canais.", "hint": "Quem produz jobs fecha jobs; outro coordenador espera workers e fecha results.", "solution": "Crie jobs e results, três consumidores, produtor que fecha jobs e uma espera que fecha results. O consumidor drena results. Inclua contexto antes de usar em uma aplicação real.", "criteria": ["Concorrência limitada a três.", "Não fecha results antes do último envio."]}, {"id": 3, "title": "Pressão na fila", "prompt": "Explique o que ocorre se chegarem mil tarefas por segundo e só cem forem processadas. Defina uma política.", "hint": "Buffer maior adia o problema, mas não resolve capacidade.", "solution": "A fila cresce até esgotar memória ou atingir limite. Escolha backpressure, rejeição controlada ou fila durável com limites, prazo e observabilidade.", "criteria": ["Reconhece o limite de capacidade.", "Define uma política concreta."]}], "source": "https://pkg.go.dev/sync", "caution": "", "local": true, "minutes": 60}, {"id": 19, "level": 7, "week": 19, "title": "Handlers, rotas e contratos HTTP", "goal": "Construir uma API com a biblioteca padrão.", "theory": [{"title": "Handler é uma interface pequena", "text": "http.Handler define ServeHTTP(ResponseWriter, *Request). HandlerFunc adapta uma função. ServeMux nas versões atuais aceita padrões com método e variáveis de caminho. Prefira um mux próprio em vez do mux global, especialmente quando houver múltiplos serviços ou endpoints de diagnóstico."}, {"title": "Resposta tem uma ordem", "text": "Defina headers antes de WriteHeader ou Write. A primeira escrita do corpo envia status 200 se nada foi definido. Separe erros de validação, ausência, conflito e falha interna. Nunca exponha um stack trace ou credencial ao cliente."}, {"title": "Teste sem precisar de um deploy", "text": "Use httptest para enviar uma requisição ao handler. Compare status, tipo de conteúdo e o contrato do JSON. Em um servidor real, configure timeouts compatíveis com a carga, cancelamento e shutdown. O exemplo abaixo testa a resposta em memória e não abre uma porta."}], "code": "package main\nimport (\n    \"fmt\"\n    \"net/http\"\n    \"net/http/httptest\"\n)\nfunc main() {\n    mux := http.NewServeMux()\n    mux.HandleFunc(\"GET /ordens/{id}\", func(w http.ResponseWriter, r *http.Request) {\n        w.Header().Set(\"Content-Type\", \"text/plain; charset=utf-8\")\n        fmt.Fprint(w, \"OS-\"+r.PathValue(\"id\"))\n    })\n    rr := httptest.NewRecorder()\n    mux.ServeHTTP(rr, httptest.NewRequest(\"GET\", \"/ordens/7\", nil))\n    fmt.Println(rr.Code, rr.Body.String())\n}\n", "expected": "200 OS-7", "quiz": {"question": "Quando definir Content-Type?", "options": ["Após escrever o corpo", "Antes de WriteHeader ou Write", "Apenas no banco", "Nunca em JSON"], "answer": 1, "explanation": "A primeira escrita pode enviar os headers. Alterá-los depois normalmente já é tarde."}, "exercises": [{"id": 1, "title": "Detalhe por ID", "prompt": "Implemente GET /ordens/{id}, com 200 para existente, 400 para ID malformado e 404 para ausente.", "hint": "Separe converter o parâmetro de buscar a ordem.", "solution": "Parseie o ID com strconv, valide faixa, consulte um repositório e mapeie os erros do domínio para os status. Não transforme toda falha em 500.", "criteria": ["Testa os três caminhos.", "Não expõe erro interno no corpo."]}, {"id": 2, "title": "Criação consistente", "prompt": "Defina o contrato de POST /ordens: entrada, resposta, status e Location.", "hint": "Pense em recurso criado e endereço de consulta.", "solution": "Uma criação bem-sucedida pode devolver 201, Location: /ordens/{id} e JSON com o recurso. Documente os campos obrigatórios e erros de validação.", "criteria": ["Define 201 e Location.", "Entrada e resposta têm exemplos."]}, {"id": 3, "title": "Escrita prematura", "prompt": "Investigue por que fmt.Fprint(w, \"erro\"); w.WriteHeader(400) não produz a resposta esperada.", "hint": "A escrita do corpo já escolheu um status.", "solution": "Fprint envia implicitamente 200 se nenhum status foi escrito. A correção é definir headers/status antes do corpo.", "criteria": ["Explica o 200 implícito.", "Reordena as operações."]}], "source": "https://pkg.go.dev/net/http", "caution": "", "local": false, "minutes": 60}, {"id": 20, "level": 7, "week": 20, "title": "Clientes HTTP e middleware", "goal": "Tratar a rede como uma fronteira que pode demorar ou falhar.", "theory": [{"title": "Reutilize o cliente", "text": "http.Client e seu Transport foram feitos para reutilização e são seguros para uso concorrente. Configure prazo e contexto em vez de depender de uma chamada sem limite. Feche resp.Body, inclusive em status de erro. Leia ou drene dentro de limites quando isso fizer parte da política de reutilização."}, {"title": "Status de erro não é erro de transporte", "text": "client.Do pode retornar err nil e uma resposta HTTP 500. Verifique status e trate falhas de decodificação. Limite o tamanho da resposta. Repetir automaticamente um POST pode duplicar efeitos; retry precisa de contrato de idempotência, prazo total e backoff com jitter."}, {"title": "Middleware é composição", "text": "Um middleware recebe http.Handler e devolve http.Handler. É útil para request ID, logs, recuperação controlada e autenticação. Defina a ordem de execução e não suponha que CORS substitui autenticação. Instrumentar ResponseWriter requer cuidado com interfaces opcionais e streaming."}], "code": "package main\nimport (\n    \"fmt\"\n    \"net/http\"\n    \"net/http/httptest\"\n)\nfunc requestID(next http.Handler) http.Handler {\n    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n        w.Header().Set(\"X-Request-ID\", \"exemplo-local\")\n        next.ServeHTTP(w, r)\n    })\n}\nfunc main() {\n    rr := httptest.NewRecorder()\n    h := requestID(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(204) }))\n    h.ServeHTTP(rr, httptest.NewRequest(\"GET\", \"/\", nil))\n    fmt.Println(rr.Code, rr.Header().Get(\"X-Request-ID\"))\n}\n", "expected": "204 exemplo-local", "quiz": {"question": "client.Do devolveu resposta 500 e err nil. Isso é possível?", "options": ["Não", "Sim; o transporte funcionou, mas o servidor respondeu com erro HTTP", "Só no Playground", "Significa sucesso do negócio"], "answer": 1, "explanation": "Erro de transporte e status HTTP são níveis diferentes. Ambos exigem tratamento."}, "exercises": [{"id": 1, "title": "Cliente com prazo", "prompt": "Escreva uma chamada com NewRequestWithContext, cliente reutilizável e fechamento de Body.", "hint": "Verifique Do antes de acessar resp.", "solution": "Crie um contexto com prazo, defer cancel, monte a requisição, chame um cliente reutilizado, trate err e então defer resp.Body.Close(). Confira status e limite o corpo.", "criteria": ["Trata transporte e status.", "Tem prazo e limite de leitura."]}, {"id": 2, "title": "Teste de indisponibilidade", "prompt": "Use httptest.NewServer para devolver 503 e verifique o erro do seu cliente.", "hint": "O teste não deve depender da internet.", "solution": "O servidor de teste sempre responde 503. O cliente deve classificar indisponibilidade sem fingir que a resposta foi um recurso válido.", "criteria": ["Sem rede externa.", "Verifica classificação e mensagem útil."]}, {"id": 3, "title": "Repetição de POST", "prompt": "Um timeout ocorreu após enviar a criação de uma OS. Explique por que repetir pode duplicar e como evitar.", "hint": "O servidor pode ter confirmado a transação antes de a resposta se perder.", "solution": "Use uma chave de idempotência persistida com unicidade e resultado associado. Repetições retornam o mesmo resultado ou um conflito documentado.", "criteria": ["Reconhece resultado desconhecido.", "Propõe deduplicação persistente."]}], "source": "https://pkg.go.dev/net/http#Client", "caution": "", "local": false, "minutes": 60}, {"id": 21, "level": 7, "week": 21, "title": "Segurança na fronteira da API", "goal": "Validar, autorizar e limitar antes de executar efeitos.", "theory": [{"title": "Identidade e permissão são diferentes", "text": "Autenticação identifica quem chama; autorização decide o que essa identidade pode fazer naquele recurso. Um técnico autenticado ainda precisa estar autorizado para a OS consultada. Nunca confie em tecnico_id recebido do cliente para decidir sozinho o escopo."}, {"title": "Entradas e saídas têm limites", "text": "Use MaxBytesReader para limitar corpo HTTP. Para JSON estrito, combine DisallowUnknownFields com uma segunda Decode que exija EOF, evitando múltiplos valores. Defina limites de cabeçalho, paginação, upload e tempo. Validação de formato não substitui autorização."}, {"title": "Segredos e dependências", "text": "Senhas precisam de hashing lento apropriado, como Argon2id ou bcrypt com parâmetros avaliados; criptografia reversível não é armazenamento de senha. Cookies de sessão precisam de política adequada de Secure, HttpOnly e SameSite e proteção contra CSRF quando aplicável. Consulte a documentação do provedor escolhido e use govulncheck nas dependências. A aula não entrega um sistema de autenticação pronto para produção."}], "code": "package main\nimport (\n    \"encoding/json\"\n    \"fmt\"\n    \"strings\"\n)\nfunc main() {\n    var entrada struct { Status string `json:\"status\"` }\n    dec := json.NewDecoder(strings.NewReader(`{\"status\":\"aberta\",\"admin\":true}`))\n    dec.DisallowUnknownFields()\n    err := dec.Decode(&entrada)\n    fmt.Println(err != nil)\n}\n", "expected": "true", "quiz": {"question": "Um usuário autenticado pode acessar qualquer OS por conhecer seu ID?", "options": ["Sim", "Só se o ID for longo", "Não; deve haver autorização sobre o recurso", "CORS resolve isso"], "answer": 2, "explanation": "Conhecer o ID e possuir uma sessão não dá permissão. A consulta precisa aplicar o escopo e a política do recurso."}, "exercises": [{"id": 1, "title": "Matriz de autorização", "prompt": "Defina acesso de técnico, operador e administrador para visualizar e concluir uma OS.", "hint": "Separe concluir execução de confirmar operacionalmente.", "solution": "Técnico acessa suas ordens e envia evidências; confirmação operacional exige papel e permissão adequados. Teste explicitamente acesso cruzado entre técnicos.", "criteria": ["Inclui autorização por recurso.", "Tem teste de acesso cruzado."]}, {"id": 2, "title": "JSON estrito", "prompt": "Projete um decoder que rejeite corpo excessivo, campo desconhecido e segundo objeto JSON.", "hint": "A primeira Decode bem-sucedida não garante fim do corpo.", "solution": "Use MaxBytesReader no handler; DisallowUnknownFields; primeira Decode; segunda Decode para verificar io.EOF. Classifique tamanho excessivo e JSON inválido conforme o contrato.", "criteria": ["Rejeita os três casos.", "Não expõe detalhes internos."]}, {"id": 3, "title": "Auditoria sem vazamento", "prompt": "Liste o que registrar na confirmação de uma OS e o que excluir do log.", "hint": "Rastreabilidade não exige registrar toda a requisição.", "solution": "Registre ator, recurso, ação, resultado, instante e request ID. Exclua senha, token, segredo e conteúdo de evidências; trate dados pessoais com escopo mínimo.", "criteria": ["Evento permite rastrear a ação.", "Não registra segredos."]}], "source": "https://go.dev/doc/security/", "caution": "Autenticação e autorização exigem revisão própria antes de usar o projeto com dados reais.", "local": false, "minutes": 60}, {"id": 22, "level": 8, "week": 22, "title": "SQL, pool e consultas parametrizadas", "goal": "Acessar dados com contexto e recursos bem administrados.", "theory": [{"title": "sql.DB é um pool", "text": "database/sql fornece abstrações para drivers. sql.DB gerencia conexões, não representa uma única sessão. Configure limites conforme o banco e a aplicação; mais conexões não significam mais desempenho. Use PingContext para verificar conectividade dentro de um prazo."}, {"title": "Dados não são código SQL", "text": "Passe valores como parâmetros para QueryContext e ExecContext. Placeholders dependem do driver; no PostgreSQL, $1 é comum. Nomes de tabelas e colunas não são parâmetros: para ordenação dinâmica, use uma lista permitida de identificadores definidos pelo programa."}, {"title": "O ciclo da consulta", "text": "QueryRowContext(...).Scan pode devolver sql.ErrNoRows, que normalmente vira ausência no domínio. Em QueryContext, feche rows, verifique cada Scan e confira rows.Err depois do laço. Passe o contexto da requisição até o driver para permitir cancelamento."}], "code": "package main\nimport (\n    \"context\"\n    \"database/sql\"\n    \"fmt\"\n)\nfunc buscarStatus(ctx context.Context, db *sql.DB, id int64) (string, error) {\n    var status string\n    err := db.QueryRowContext(ctx, \"SELECT status FROM ordens WHERE id = $1\", id).Scan(&status)\n    if err != nil { return \"\", fmt.Errorf(\"buscar ordem: %w\", err) }\n    return status, nil\n}\nfunc main() { fmt.Println(\"Função de repositório; requer driver e banco PostgreSQL para consulta real.\") }\n", "expected": "Função de repositório; requer driver e banco PostgreSQL para consulta real.", "quiz": {"question": "O que representa *sql.DB?", "options": ["Uma linha", "Um pool de conexões gerenciado", "Uma transação única", "Um driver PostgreSQL embutido"], "answer": 1, "explanation": "database/sql gerencia o pool. O driver é separado e precisa ser escolhido e configurado."}, "exercises": [{"id": 1, "title": "Consulta segura", "prompt": "Implemente busca por ID e técnico usando parâmetros PostgreSQL. Não concatene valores.", "hint": "Use WHERE id = $1 AND tecnico_id = $2.", "solution": "Passe ambos os valores a QueryRowContext e mapeie sql.ErrNoRows sem revelar existência de recurso fora do escopo. Adicione um driver compatível no módulo.", "criteria": ["Usa parâmetros.", "Aplica escopo por técnico."]}, {"id": 2, "title": "Recursos da listagem", "prompt": "Descreva o fluxo completo de QueryContext com múltiplas linhas e todos os erros relevantes.", "hint": "Existe um erro possível depois de a última iteração terminar.", "solution": "Trate o erro inicial, defer rows.Close, faça Scan por linha, trate cada falha e verifique rows.Err no final. Limite a paginação.", "criteria": ["Inclui rows.Err.", "Limita a quantidade de dados."]}, {"id": 3, "title": "Ordenação permitida", "prompt": "O usuário pede order_by. Proponha uma implementação segura para criado_em e status.", "hint": "Valores são parâmetros; identificadores vêm de uma tabela controlada.", "solution": "Mapeie entradas conhecidas para fragmentos fixos como \"created_at\" e \"status\". Rejeite desconhecidos. Não aceite expressão SQL arbitrária.", "criteria": ["Lista explícita de opções.", "Não concatena texto livre."]}], "source": "https://go.dev/doc/tutorial/database-access", "caution": "", "local": true, "minutes": 60}, {"id": 23, "level": 8, "week": 23, "title": "Transações e idempotência", "goal": "Preservar invariáveis quando operações falham ou competem.", "theory": [{"title": "Tudo ou nada dentro da fronteira", "text": "Uma transação agrupa operações no mesmo banco. BeginTx devolve *sql.Tx. Use o tx para todas as consultas que pertencem à transação; usar db no meio pode obter outra conexão e escapar da atomicidade. Defer Rollback cobre saídas antecipadas; Commit também pode falhar."}, {"title": "Concorrência exige uma decisão", "text": "Duas confirmações da mesma OS podem chegar juntas. Use estado com update condicional, locks apropriados, nível de isolamento e restrições de unicidade conforme a regra. Teste com duas transações concorrentes reais. A escolha depende do comportamento específico do banco e do driver."}, {"title": "Efeito externo é outra fronteira", "text": "Uma transação SQL não desfaz um webhook já enviado. O padrão outbox grava a mudança e um evento na mesma transação; um worker publica depois com deduplicação. Idempotência significa repetir a mesma intenção sem duplicar o efeito de negócio, e precisa sobreviver a reinícios."}], "code": "package main\nimport (\n    \"context\"\n    \"database/sql\"\n    \"errors\"\n    \"fmt\"\n)\nfunc confirmar(ctx context.Context, db *sql.DB, id int64) error {\n    tx, err := db.BeginTx(ctx, nil)\n    if err != nil { return err }\n    defer tx.Rollback()\n    r, err := tx.ExecContext(ctx, \"UPDATE ordens SET status='concluida' WHERE id=$1 AND status='pendente'\", id)\n    if err != nil { return err }\n    n, err := r.RowsAffected()\n    if err != nil { return err }\n    if n != 1 { return errors.New(\"ordem ausente ou estado incompatível\") }\n    return tx.Commit()\n}\nfunc main() { fmt.Println(\"Exemplo parcial: a baixa de estoque deve integrar a mesma transação.\") }\n", "expected": "Exemplo parcial: a baixa de estoque deve integrar a mesma transação.", "quiz": {"question": "Uma operação feita por db dentro de uma função que abriu tx pertence automaticamente à transação?", "options": ["Sim", "Não; é preciso usar o tx", "Só se tiver o mesmo SQL", "Só em PostgreSQL"], "answer": 1, "explanation": "A transação usa sua conexão. Operações no pool db não entram automaticamente nela."}, "exercises": [{"id": 1, "title": "OS e estoque juntos", "prompt": "Desenhe a confirmação operacional e a baixa do IMEI em uma única transação.", "hint": "Toda mudança no banco usa tx, e o estado anterior limita o update.", "solution": "Valide a transição, atualize a OS condicionalmente, baixe o equipamento vinculado e grave auditoria/outbox no mesmo tx. Qualquer falha cancela tudo. Não peça uma nova leitura de IMEI se a instalação já o vinculou.", "criteria": ["Atomicidade de OS e equipamento.", "Concorrência não duplica a baixa."]}, {"id": 2, "title": "Duas confirmações", "prompt": "Especifique um teste de integração com duas confirmações simultâneas da mesma OS.", "hint": "O resultado do estoque precisa ser verificado após as duas terminarem.", "solution": "Inicie operações sincronizadas, aguarde ambas e confira uma única baixa, um estado final coerente e respostas segundo a política de idempotência/conflito.", "criteria": ["Exercita concorrência real no banco.", "Verifica efeito persistido, não só status HTTP."]}, {"id": 3, "title": "Falha no webhook", "prompt": "O banco confirmou, mas o envio externo falhou. Descreva recuperação com outbox.", "hint": "Salvar evento e mudança juntos fecha a lacuna entre commit e envio.", "solution": "O worker busca eventos pendentes, envia, registra sucesso e tenta novamente com backoff em falhas. O receptor ou protocolo precisa deduplicar porque o envio pode ocorrer mais de uma vez.", "criteria": ["Persistência do evento é transacional.", "Reconhece entrega duplicada possível."]}], "source": "https://go.dev/doc/database/execute-transactions", "caution": "", "local": true, "minutes": 60}, {"id": 24, "level": 8, "week": 24, "title": "Arquitetura guiada por dependências", "goal": "Organizar o projeto sem transformar toda função em uma camada.", "theory": [{"title": "Comece pelas regras", "text": "A regra de concluir uma OS não deve depender de detalhes de HTTP ou do driver SQL. Uma função de aplicação pode coordenar autorização e persistência por contratos pequenos. A arquitetura existe para tornar mudanças e verificações mais fáceis, não para maximizar pastas."}, {"title": "Interfaces onde há consumidor", "text": "Declare uma interface perto da regra que a utiliza. Implemente detalhes de banco e rede na borda, fazendo a composição em main. Evite interfaces enormes, containers de injeção desnecessários e modelos de domínio que só espelham a tabela sem carregar regras."}, {"title": "Leia o grafo de dependências", "text": "Pacotes Go não podem ter ciclos de importação. Se dois pacotes se conhecem demais, revise a responsabilidade e a direção da dependência. Registre decisões difíceis com alternativas, restrições e consequências. Só extraia microserviços quando limites operacionais e de equipe justificarem."}], "code": "package main\nimport (\n    \"context\"\n    \"fmt\"\n)\ntype Repositorio interface { Status(context.Context, int) (string, error) }\ntype Memoria map[int]string\nfunc (m Memoria) Status(ctx context.Context, id int) (string, error) {\n    s, ok := m[id]\n    if !ok { return \"\", fmt.Errorf(\"ordem ausente\") }\n    return s, nil\n}\nfunc consultar(ctx context.Context, r Repositorio, id int) (string, error) { return r.Status(ctx, id) }\nfunc main() {\n    s, err := consultar(context.Background(), Memoria{1:\"aberta\"}, 1)\n    if err != nil { fmt.Println(err); return }\n    fmt.Println(s)\n}\n", "expected": "aberta", "quiz": {"question": "Onde costuma fazer sentido declarar uma interface pequena de dependência?", "options": ["Sempre em um pacote global interfaces", "Perto do consumidor que precisa do comportamento", "Dentro do driver SQL obrigatoriamente", "Uma interface para cada struct"], "answer": 1, "explanation": "O consumidor define o comportamento que necessita. Isso evita acoplá-lo a uma API maior que sua necessidade."}, "exercises": [{"id": 1, "title": "Mapa de pacotes", "prompt": "Proponha a estrutura de um monólito de OS e descreva a direção das importações.", "hint": "O comando monta dependências; regras não importam handlers.", "solution": "Uma opção: cmd/api compõe internal/ordem, internal/httpapi e internal/postgres. As bordas dependem dos contratos do domínio/aplicação, sem ciclo.", "criteria": ["Sem ciclos.", "Responsabilidades justificadas."]}, {"id": 2, "title": "Troca de armazenamento", "prompt": "Demonstre que uma regra usa um fake em memória sem importar database/sql.", "hint": "A assinatura da dependência pertence ao comportamento necessário.", "solution": "Implemente apenas os métodos consumidos pelo caso de uso. Um teste injeta o fake e observa o resultado/efeito, sem duplicar a implementação SQL.", "criteria": ["Regra independente de SQL.", "O fake testa comportamento real do caso de uso."]}, {"id": 3, "title": "Decisão registrada", "prompt": "Escreva uma decisão: monólito modular ou microserviços para seu projeto de estudo.", "hint": "Considere deploy, transações, diagnóstico e equipe de uma pessoa.", "solution": "O monólito modular costuma reduzir custo operacional inicial. Registre o contexto, a decisão e os sinais concretos que justificariam separação futura.", "criteria": ["Expõe alternativas e consequências.", "Usa restrições reais."]}], "source": "https://go.dev/doc/modules/layout", "caution": "", "local": true, "minutes": 60}, {"id": 25, "level": 9, "week": 25, "title": "Generics e conjuntos de tipos", "goal": "Criar uma abstração genérica com uma razão concreta.", "theory": [{"title": "O parâmetro é um tipo", "text": "Uma função genérica recebe parâmetros de tipo entre colchetes e valores entre parênteses. A restrição define quais tipos podem ser usados e quais operações são válidas. any aceita qualquer tipo; comparable permite igualdade e uso como chave de map dentro das regras da linguagem."}, {"title": "Conjuntos e tipo subjacente", "text": "Uma restrição como ~int | ~int64 aceita tipos cujo tipo subjacente é int ou int64. O til permite que tipos definidos do domínio participem do contrato. Isso não remove risco de overflow: uma função genérica ainda precisa de limites ou de uma política aritmética."}, {"title": "Abstração deve pagar seu custo", "text": "Generics combinam bem com estruturas de dados e algoritmos que preservam relações entre tipos. Interfaces comuns continuam apropriadas para comportamentos. Evite transformar uma simples chamada concreta em uma API genérica sem consumidor real. Documente casos vazios, mutação e propriedade dos dados."}], "code": "package main\nimport \"fmt\"\ntype Inteiro interface { ~int | ~int64 }\nfunc Somar[T Inteiro](valores []T) T {\n    var total T\n    for _, v := range valores { total += v }\n    return total\n}\ntype Centavos int64\nfunc main() { fmt.Println(Somar([]Centavos{100, 200, 50})) }\n", "expected": "350", "quiz": {"question": "Por que usar ~int64 em uma restrição?", "options": ["Para aceitar qualquer tipo", "Para aceitar tipos definidos cujo tipo subjacente é int64", "Para converter strings automaticamente", "Para eliminar overflow"], "answer": 1, "explanation": "~ descreve o tipo subjacente no conjunto de tipos. Não é uma conversão e não muda a aritmética."}, "exercises": [{"id": 1, "title": "Contém genérico", "prompt": "Implemente Contem[T comparable]([]T, T) bool e teste string, int e slice vazio.", "hint": "Compare cada elemento ao alvo usando ==.", "solution": "Percorra os valores, retorne true no primeiro igual e false no final. Comparable é necessária porque a implementação usa igualdade.", "criteria": ["Passa nos três cenários.", "Justifica a restrição."]}, {"id": 2, "title": "Tipo do domínio", "prompt": "Use type Centavos int64 com Somar e explique por que Inteiro com apenas int64 não aceitaria o tipo definido.", "hint": "Um tipo definido não é idêntico ao tipo subjacente.", "solution": "Sem ~, o termo int64 representa esse tipo exato. ~int64 inclui tipos definidos com esse subjacente, como Centavos.", "criteria": ["Distingue identidade de subjacência.", "Demonstra a restrição adequada."]}, {"id": 3, "title": "Quando recusar generics", "prompt": "Compare interface Notificador com uma função genérica para avisar a conclusão de OS. Qual contrato fica mais claro?", "hint": "A necessidade aqui é comportamento, não aritmética de coleções.", "solution": "Uma interface pequena costuma expressar melhor Avisar. A solução deve justificar sua escolha com consumidores reais, sem assumir que generics sempre melhoram desempenho.", "criteria": ["Compara contratos.", "Não promete velocidade sem medir."]}], "source": "https://go.dev/doc/tutorial/generics", "caution": "", "local": false, "minutes": 60}, {"id": 26, "level": 9, "week": 26, "title": "Iteradores e evolução da linguagem", "goal": "Ler recursos modernos respeitando sua versão mínima.", "theory": [{"title": "Iterar sem materializar tudo", "text": "Desde Go 1.23, range pode consumir funções com assinaturas específicas. iter.Seq[T] representa uma sequência cujo produtor recebe yield func(T) bool. Quando yield retorna false, o produtor deve parar. Isso permite encerrar cedo sem precisar criar um slice com todos os elementos."}, {"title": "Recursos têm uma versão", "text": "A diretiva go do módulo participa das regras de linguagem disponíveis. Ao usar um recurso novo, registre a versão mínima e teste com ela. As notas de Go 1.27 introduzem métodos com seus próprios parâmetros de tipo; métodos de interfaces continuam sem poder declarar esses parâmetros e não são implementados por métodos genéricos."}, {"title": "Modernize com julgamento", "text": "Conheça go fix e bibliotecas como slices, maps e iter, mas não atualize uma API pública só para exibir sintaxe nova. Compare clareza, compatibilidade e custo. O exemplo usa iteradores de Go 1.23; a leitura complementar aborda os limites dos métodos genéricos em Go 1.27."}], "code": "package main\nimport (\n    \"fmt\"\n    \"iter\"\n)\nfunc Numeros(n int) iter.Seq[int] {\n    return func(yield func(int) bool) {\n        for i := 1; i <= n; i++ {\n            if !yield(i) { return }\n        }\n    }\n}\nfunc main() {\n    for v := range Numeros(5) {\n        fmt.Println(v)\n        if v == 2 { break }\n    }\n}\n", "expected": "1\n2", "quiz": {"question": "O que um produtor iter.Seq deve fazer se yield devolver false?", "options": ["Continuar produzindo", "Encerrar a iteração", "Fechar um canal inexistente", "Reiniciar a sequência"], "answer": 1, "explanation": "False informa que o consumidor não quer mais valores. Continuar chamando yield viola o protocolo."}, "exercises": [{"id": 1, "title": "Iterador filtrado", "prompt": "Crie um iterador que produza apenas os números pares de 1 até n e respeite a interrupção.", "hint": "Só chame yield para os pares e retorne quando vier false.", "solution": "Percorra os números, filtre com i%2 == 0 e encerre em !yield(i). Teste um consumidor que para no primeiro par.", "criteria": ["Produz a sequência correta.", "Para quando o consumidor pede."]}, {"id": 2, "title": "Versão explícita", "prompt": "Defina a versão mínima de um módulo que usa range sobre iter.Seq e explique como verificar compatibilidade.", "hint": "Consulte as notas oficiais da versão do recurso.", "solution": "Range sobre funções iteradoras requer Go 1.23 ou posterior. Teste no toolchain mínimo declarado e no estável atual; não confunda a versão instalada com a versão declarada.", "criteria": ["Registra Go 1.23 como mínimo desse recurso.", "Define verificação real."]}, {"id": 3, "title": "Métodos genéricos em 1.27", "prompt": "Leia as notas oficiais do Go 1.27 e explique um caso de uso e uma limitação dos métodos genéricos.", "hint": "Uma regra sobre métodos de interface permanece restritiva.", "solution": "Podem manter uma transformação genérica no namespace de um tipo. Métodos de interfaces não podem declarar parâmetros de tipo próprios nem ser implementados por métodos genéricos. Exija Go 1.27 para código que usa a novidade.", "criteria": ["Cita a restrição de interfaces.", "Explicita a versão mínima."]}], "source": "https://go.dev/doc/go1.27", "caution": "O exemplo de iterador exige Go 1.23+. A extensão de métodos genéricos citada na aula exige Go 1.27+.", "local": false, "minutes": 60}, {"id": 27, "level": 9, "week": 27, "title": "Reflection e contratos dinâmicos", "goal": "Inspecionar tipos sem substituir validação por fragilidade.", "theory": [{"title": "Tipos durante a execução", "text": "reflect permite inspecionar tipos, campos e valores dinamicamente. Bibliotecas de serialização usam essas capacidades. Type descreve o tipo; Value representa um valor refletido. Kind é a categoria, como struct ou ptr, e não identifica sozinho um tipo definido."}, {"title": "Modificar exige permissão", "text": "Um reflect.Value só pode ser alterado em condições de endereçabilidade e exportação. Use CanSet e verifique Kind antes de chamar operações específicas. O código pode causar panic se presumir um formato que não existe. Tags de struct são metadados, não uma validação automática de regra de negócio."}, {"title": "Escolha uma alternativa mais simples", "text": "Antes de reflection, considere código concreto, interfaces, generics ou geração de código. Reflection desloca erros para a execução e dificulta leitura. Use-a em uma fronteira bem testada, com mensagens úteis, limites e documentação dos tipos aceitos."}], "code": "package main\nimport (\n    \"fmt\"\n    \"reflect\"\n)\ntype Ordem struct { ID int `json:\"id\"` }\nfunc main() {\n    t := reflect.TypeOf(Ordem{})\n    campo, ok := t.FieldByName(\"ID\")\n    if !ok { return }\n    fmt.Println(campo.Name, campo.Tag.Get(\"json\"))\n}\n", "expected": "ID id", "quiz": {"question": "Uma tag json:\"id\" valida automaticamente que ID seja positivo?", "options": ["Sim", "Não; a tag orienta bibliotecas, a regra precisa ser implementada", "Só com reflect", "Somente em interfaces"], "answer": 1, "explanation": "Tags são metadados. encoding/json interpreta o nome, mas não implementa essa invariável do domínio."}, "exercises": [{"id": 1, "title": "Leitor de metadados", "prompt": "Liste nomes e tags json de campos exportados de um struct recebido como tipo.", "hint": "Valide se o tipo é struct antes de iterar campos.", "solution": "Use Kind, NumField e Field; trate ponteiros conforme o contrato e filtre campos privados. Não presuma que qualquer valor serve.", "criteria": ["Rejeita formatos incompatíveis.", "Não expõe campos privados indevidamente."]}, {"id": 2, "title": "Por que panic?", "prompt": "Explique por que reflect.ValueOf(3).SetInt(4) falha e construa um valor modificável.", "hint": "O valor precisa apontar para armazenamento endereçável.", "solution": "Use x := 3; v := reflect.ValueOf(&x).Elem(); confirme v.CanSet(); v.SetInt(4). O valor refletido de um literal não é modificável.", "criteria": ["Explica endereçabilidade.", "Verifica CanSet e tipo."]}, {"id": 3, "title": "Revisão de desenho", "prompt": "Uma regra de OS usa reflection para acessar Status por nome. Proponha uma alternativa.", "hint": "A estrutura do domínio já é conhecida em compilação.", "solution": "Use um tipo concreto ou uma interface com operação significativa. Isso move verificações para a compilação e evita strings de nomes de campo espalhadas.", "criteria": ["Elimina dependência de nomes textuais.", "Mantém o contrato explícito."]}], "source": "https://go.dev/blog/laws-of-reflection", "caution": "", "local": false, "minutes": 60}, {"id": 28, "level": 10, "week": 28, "title": "Benchmarks, pprof e diagnóstico", "goal": "Localizar o gargalo antes de alterar o código.", "theory": [{"title": "Uma hipótese verificável", "text": "Descreva uma carga representativa e a métrica que importa: latência, throughput, alocações ou memória retida. Um microbenchmark isolado pode não representar o sistema. Meça o caminho real e investigue se o custo é CPU, I/O, contenção ou dependência externa."}, {"title": "Ferramentas complementares", "text": "go test -bench e -benchmem ajudam em microbenchmarks. pprof mostra perfis amostrados de CPU, heap e outros recursos. go tool trace ajuda a entender eventos do runtime e períodos de bloqueio. Ative perfis com cuidado e proteja os endpoints de diagnóstico."}, {"title": "Compare com disciplina", "text": "Use entradas equivalentes e versões registradas; execute múltiplas amostras e compare a variabilidade. Preserve testes de correção. O exemplo é um benchmark local, não um número de desempenho predefinido. A ferramenta atual também oferece formas modernas de loop de benchmark, conforme sua versão."}], "code": "package main\nimport (\n    \"strconv\"\n    \"strings\"\n    \"testing\"\n)\nfunc montar(n int) string {\n    var b strings.Builder\n    for i := 0; i < n; i++ { b.WriteString(strconv.Itoa(i)) }\n    return b.String()\n}\nfunc BenchmarkMontar(b *testing.B) {\n    b.ReportAllocs()\n    for i := 0; i < b.N; i++ { _ = montar(100) }\n}\n", "expected": "Em main_test.go: go test -run=^$ -bench=Montar -benchmem -count=5 .", "quiz": {"question": "Qual é o primeiro passo de uma otimização útil?", "options": ["Trocar tudo por ponteiros", "Definir carga, métrica e hipótese mensurável", "Adicionar goroutines", "Usar unsafe"], "answer": 1, "explanation": "Sem carga e objetivo, uma melhoria local pode aumentar o custo do sistema ou não beneficiar o usuário."}, "exercises": [{"id": 1, "title": "Linha de base", "prompt": "Registre cinco amostras de um benchmark com versão de Go, máquina e tamanho de entrada.", "hint": "Não preencha números estimados: rode localmente.", "solution": "Guarde saídas reais de -benchmem e -count=5, e descreva o que a preparação inclui. Use uma comparação estatística apropriada quando comparar alterações.", "criteria": ["Resultados reais e reproduzíveis.", "Inclui B/op e allocs/op."]}, {"id": 2, "title": "Perfil com pergunta", "prompt": "Colete CPU ou heap do projeto e formule uma hipótese baseada no perfil.", "hint": "Heap vivo e total alocado respondem perguntas diferentes.", "solution": "Escolha o perfil ligado ao sintoma. Identifique uma pilha relevante, faça uma mudança pequena e reavalie a mesma carga com os mesmos testes.", "criteria": ["Hipótese cita evidência.", "Reavalia depois da mudança."]}, {"id": 3, "title": "Latência externa", "prompt": "Uma API está lenta, mas usa pouca CPU. Liste investigações antes de micro-otimizar JSON.", "hint": "Observe espera no banco, rede e filas.", "solution": "Meça tempo por dependência, pool de conexões, locks, filas, timeouts e tamanho de resposta. CPU baixa pode indicar tempo bloqueado.", "criteria": ["Considera I/O e contenção.", "Define como medir cada hipótese."]}], "source": "https://go.dev/doc/diagnostics", "caution": "", "local": true, "minutes": 60}, {"id": 29, "level": 10, "week": 29, "title": "Memória, escape analysis e GC", "goal": "Distinguir alocação, retenção e coleta.", "theory": [{"title": "A vida do valor importa", "text": "O compilador decide se armazenamento pode ficar na stack ou precisa sobreviver em outro lugar. Escape analysis acompanha esse uso. Retornar o endereço de uma variável local é seguro em Go: o armazenamento sobrevive conforme necessário. A decisão exata de alocação é detalhe da implementação e pode mudar."}, {"title": "GC não corrige retenção lógica", "text": "O garbage collector recupera objetos que deixaram de ser alcançáveis. Se um slice pequeno mantém referência a um array grande, esse array pode permanecer vivo. Maps, caches e goroutines bloqueadas também podem manter dados desnecessários. Memória retida não é o mesmo que taxa de alocação."}, {"title": "Ajuste depois de medir", "text": "GOGC e GOMEMLIMIT influenciam o comportamento de memória do runtime; o limite de memória é uma orientação do runtime, não uma barreira rígida contra todo consumo do processo. Revise o guia de GC e a versão usada. sync.Pool não garante persistência dos objetos e deve ser justificado por perfil."}], "code": "package main\nimport \"fmt\"\nfunc independente(dados []byte, n int) []byte {\n    if n < 0 || n > len(dados) { return nil }\n    copia := make([]byte, n)\n    copy(copia, dados[:n])\n    return copia\n}\nfunc main() {\n    origem := []byte(\"OS-001:conteúdo longo\")\n    id := independente(origem, 6)\n    origem[0] = 'X'\n    fmt.Println(string(id))\n}\n", "expected": "OS-001", "quiz": {"question": "Um subslice pequeno sempre libera o resto do array original?", "options": ["Sim", "Não; pode manter o array inteiro alcançável", "Só com GC desativado", "Só para int"], "answer": 1, "explanation": "O slice contém referência ao array subjacente. Copiar a parte necessária pode permitir liberar o array antigo."}, "exercises": [{"id": 1, "title": "Retenção por subslice", "prompt": "Construa um exemplo em que guardar os primeiros bytes de um buffer mantém o array grande referenciado. Depois copie só os bytes necessários.", "hint": "O custo de uma cópia pequena pode reduzir retenção longa.", "solution": "Compare dados[:n] com append([]byte(nil), dados[:n]...). Investigue com heap profile; não conclua apenas pelo tamanho len do slice.", "criteria": ["Explica a referência ao array.", "Separa alocação de retenção."]}, {"id": 2, "title": "Escape observado", "prompt": "Use go build -gcflags=-m no seu módulo e explique duas mensagens observadas.", "hint": "A mensagem descreve essa compilação, não uma lei imutável da linguagem.", "solution": "Registre as mensagens e a razão provável do escape. Confirme o efeito no benchmark/perfil antes de alterar a API para evitar uma alocação.", "criteria": ["Usa mensagens reais.", "Não transforma detalhe de compilador em garantia."]}, {"id": 3, "title": "Cache limitado", "prompt": "Projete um cache que não cresça indefinidamente.", "hint": "TTL sem remoção efetiva pode não limitar memória.", "solution": "Defina capacidade, política de expiração/remoção, concorrência e métricas de tamanho e hit rate. Meça o custo antes de adicionar sync.Pool.", "criteria": ["Há limite real.", "Há política de remoção e observação."]}], "source": "https://go.dev/doc/gc-guide", "caution": "", "local": true, "minutes": 60}, {"id": 30, "level": 10, "week": 30, "title": "Scheduler e modelo de memória", "goal": "Raciocinar sobre sincronização em vez de confiar na ordem aparente.", "theory": [{"title": "G, M e P como modelo de implementação", "text": "O runtime agenda goroutines sobre threads do sistema. Os termos G, M e P ajudam a ler o runtime: goroutine, thread e recurso lógico necessário para executar código Go. Esse é um modelo de implementação, não um contrato para ordenar seu programa. GOMAXPROCS limita execução paralela de código Go, não a quantidade total de goroutines."}, {"title": "Happens-before", "text": "O modelo de memória define relações de sincronização e visibilidade. Uma operação de canal, um mutex e outras primitivas podem estabelecer relações específicas. Observar que uma execução “sempre imprime certo” não prova correção; sem sincronização, leituras e escritas concorrentes podem constituir uma data race."}, {"title": "Dono do estado", "text": "Simplifique o raciocínio com uma goroutine dona de um estado ou com proteção consistente por mutex. Use atomics só com um protocolo que você consegue explicar. Avalie liveness também: ausência de race não elimina deadlock, starvation ou vazamento de goroutines."}], "code": "package main\nimport \"fmt\"\nfunc main() {\n    pronto := make(chan struct{})\n    valor := 0\n    go func() {\n        valor = 42\n        close(pronto)\n    }()\n    <-pronto\n    fmt.Println(valor)\n}\n", "expected": "42", "quiz": {"question": "Por que a leitura de valor está sincronizada no exemplo?", "options": ["Porque houve tempo suficiente", "Porque o fechamento do canal e o recebimento estabelecem a sincronização", "Porque int é sempre atômico", "Porque main tem prioridade"], "answer": 1, "explanation": "A escrita ocorre antes do close; o recebimento que observa o canal fechado cria a relação de sincronização necessária."}, "exercises": [{"id": 1, "title": "Explique a relação", "prompt": "Desenhe por escrito a sequência escrita → close → recebimento → leitura do exemplo.", "hint": "Identifique o ponto que conecta as duas goroutines.", "solution": "Na produtora, a escrita precede close. O recebimento que observa o fechamento sincroniza com ele; a leitura posterior observa o valor de acordo com o modelo de memória.", "criteria": ["Identifica a sincronização.", "Não usa tempo como justificativa."]}, {"id": 2, "title": "Sem sinalização", "prompt": "Remova o canal do exemplo e explique por que uma saída aparentemente correta não torna o programa válido.", "hint": "Não use uma execução isolada como prova.", "solution": "A leitura e a escrita deixam de estar ordenadas por sincronização e há data race. Main também pode terminar antes da goroutine. Use -race para observar caminhos, não para provar ausência universal.", "criteria": ["Aponta a race.", "Reconhece o risco de término antecipado."]}, {"id": 3, "title": "Liveness", "prompt": "Descreva um deadlock que não tenha data race e como eliminá-lo.", "hint": "Bloquear duas esperas incompatíveis já é suficiente.", "solution": "Uma única goroutine enviando em canal sem buffer antes de existir recebedor bloqueia. Reorganize produtor/consumidor e o ciclo de vida; adicionar buffer sem raciocínio pode só adiar o bloqueio.", "criteria": ["Dá exemplo sem race.", "Corrige a dependência de espera."]}], "source": "https://go.dev/ref/mem", "caution": "", "local": true, "minutes": 60}, {"id": 31, "level": 11, "week": 31, "title": "Configuração, sinais e shutdown", "goal": "Encerrar sem abandonar trabalho e sem esperar para sempre.", "theory": [{"title": "Configuração é entrada", "text": "Leia configuração na inicialização, valide antes de aceitar tráfego e informe exatamente o campo inválido sem revelar seu segredo. Separe configuração de ambiente de regras de negócio. Defina valores padrão conscientes; uma URL vazia não deve virar uma conexão silenciosa ao destino errado."}, {"title": "Sinal vira cancelamento", "text": "signal.NotifyContext converte sinais em cancelamento. Pare de aceitar novas tarefas, sinalize workers, aguarde trabalho em andamento por um prazo e feche recursos na ordem correta. HTTP Server.Shutdown é parte desse processo; recursos como conexões hijacked exigem política própria."}, {"title": "Um novo prazo para encerrar", "text": "O contexto da operação principal já pode estar cancelado ao iniciar o shutdown. Crie um contexto separado com timeout para dar uma janela de limpeza. Não bloqueie indefinidamente em uma goroutine que nunca observa cancelamento. Teste o encerramento usando sinais/controladores injetáveis quando possível."}], "code": "package main\nimport (\n    \"context\"\n    \"fmt\"\n    \"net/http\"\n    \"time\"\n)\nfunc encerrar(s *http.Server) error {\n    ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)\n    defer cancel()\n    return s.Shutdown(ctx)\n}\nfunc main() { fmt.Println(\"Integre encerrar ao recebimento de SIGTERM no seu serviço local.\") }\n", "expected": "Integre encerrar ao recebimento de SIGTERM no seu serviço local.", "quiz": {"question": "Qual contexto usar para a janela de shutdown depois de a operação principal ser cancelada?", "options": ["O mesmo contexto já cancelado", "Um contexto independente com prazo de limpeza", "Nenhum prazo", "Um valor global sem dono"], "answer": 1, "explanation": "Um contexto já cancelado encerraria a limpeza imediatamente. A janela de shutdown precisa de seu próprio prazo."}, "exercises": [{"id": 1, "title": "Encerramento completo", "prompt": "Implemente servidor que reage a SIGTERM e aguarda workers com prazo.", "hint": "Defina a ordem: parar entrada, cancelar, esperar, fechar dependências.", "solution": "Use NotifyContext; coordene Shutdown com contexto próprio e a espera dos workers. Feche o banco após tarefas que o utilizam. Trate http.ErrServerClosed como encerramento esperado.", "criteria": ["Há prazo global de limpeza.", "Não fecha dependência em uso."]}, {"id": 2, "title": "Configuração inválida", "prompt": "Defina validação para porta, URL do banco e prazo de requisição.", "hint": "Falhe antes de abrir o servidor.", "solution": "Converta e valide faixas, exija URL quando o modo precisar dela e prazo positivo. Mensagens apontam o campo sem imprimir senha ou URL com credenciais.", "criteria": ["Falha cedo.", "Não vaza segredos."]}, {"id": 3, "title": "Teste do término", "prompt": "Descreva como provar que uma tarefa em andamento pode terminar dentro da janela de shutdown.", "hint": "Sincronize início e liberação por canais.", "solution": "Inicie a tarefa, espere seu sinal de início, solicite shutdown, libere a tarefa e confira término dentro do prazo. Teste também uma tarefa que excede a janela.", "criteria": ["Testa sucesso e prazo excedido.", "Sem Sleep para coordenar."]}], "source": "https://pkg.go.dev/net/http#Server.Shutdown", "caution": "", "local": true, "minutes": 60}, {"id": 32, "level": 11, "week": 32, "title": "Logs, métricas, traces e saúde", "goal": "Responder o que falhou, onde e para quem.", "theory": [{"title": "Três perspectivas", "text": "Logs registram eventos, métricas agregam comportamento ao longo do tempo e traces conectam etapas de uma operação. log/slog fornece logs estruturados na biblioteca padrão. Inclua identificadores de correlação e campos estáveis; evite colocar dados pessoais ou segredos no log."}, {"title": "Cardinalidade custa", "text": "Uma métrica rotulada por cada ID de usuário ou OS pode produzir séries sem limite. Prefira dimensões controladas, como rota normalizada, método e classe de status. Request IDs cabem em logs e traces, não como label de alta cardinalidade em toda métrica."}, {"title": "Saúde tem significado", "text": "Liveness indica se o processo está funcional o suficiente para continuar; readiness indica se deve receber tráfego. Se a política de liveness depender de cada oscilação externa, reinícios podem amplificar uma indisponibilidade. Defina critérios, prazos e ações e não exponha diagnósticos sensíveis ao público."}], "code": "package main\nimport (\n    \"bytes\"\n    \"fmt\"\n    \"log/slog\"\n)\nfunc main() {\n    var out bytes.Buffer\n    logger := slog.New(slog.NewJSONHandler(&out, &slog.HandlerOptions{\n        ReplaceAttr: func(groups []string, a slog.Attr) slog.Attr {\n            if a.Key == slog.TimeKey { return slog.Attr{} }\n            return a\n        },\n    }))\n    logger.Info(\"ordem confirmada\", \"ordem_id\", 7, \"ator_id\", 2)\n    fmt.Print(out.String())\n}\n", "expected": "{\"level\":\"INFO\",\"msg\":\"ordem confirmada\",\"ordem_id\":7,\"ator_id\":2}", "quiz": {"question": "Qual dimensão tende a causar cardinalidade sem limite em métricas?", "options": ["Método HTTP", "Classe de status", "ID individual de cada OS", "Nome fixo de serviço"], "answer": 2, "explanation": "Cada valor distinto cria uma combinação de séries. IDs individuais costumam ser inadequados como rótulos de métricas."}, "exercises": [{"id": 1, "title": "Evento de auditoria", "prompt": "Produza um log estruturado de confirmação com ator, OS, resultado e request ID sem evidência nem token.", "hint": "Campos estruturados permitem busca sem analisar uma frase inteira.", "solution": "Use slog com campos estáveis e valores mínimos necessários. O logger pode usar contexto para correlacionar, conforme a integração escolhida.", "criteria": ["Permite correlacionar a ação.", "Não contém segredo."]}, {"id": 2, "title": "Métricas úteis", "prompt": "Escolha quatro métricas para a fila de evidências e limite os rótulos.", "hint": "Pense em tamanho, espera, duração e falha.", "solution": "Tamanho da fila, idade da tarefa mais antiga, duração de processamento e taxa de falha por categoria controlada. Não use ID de OS como label.", "criteria": ["Métricas respondem problemas operacionais.", "Rótulos são limitados."]}, {"id": 3, "title": "Saúde com política", "prompt": "Defina liveness e readiness para um serviço que depende de banco.", "hint": "Nem toda falha transitória deve reiniciar o processo.", "solution": "Readiness pode considerar capacidade de servir e dependência essencial com prazo; liveness deve refletir condição recuperável por reinício. Documente o comportamento esperado durante falha do banco.", "criteria": ["Distingue as duas políticas.", "Evita cascata de reinícios."]}], "source": "https://pkg.go.dev/log/slog", "caution": "", "local": true, "minutes": 60}, {"id": 33, "level": 11, "week": 33, "title": "CI, containers e evolução segura", "goal": "Entregar um artefato verificável sem acoplar o estudo a um provedor.", "theory": [{"title": "Um pipeline que responde perguntas", "text": "O pipeline deve formatar/verificar conforme a política, executar testes, análise estática e build. Inclua -race onde a plataforma e a carga permitirem, e govulncheck para uso conhecido de vulnerabilidades. Registre toolchain e dependências para reproduzir o resultado."}, {"title": "Artefato e configuração separados", "text": "Um container multi-stage pode compilar em uma imagem e levar só o necessário à imagem de execução. Go nem sempre gera um binário independente de bibliotecas: cgo, certificados, DNS e dados de fuso exigem atenção. Use usuário sem privilégios e nunca inclua segredos na imagem."}, {"title": "Mudança de banco também é entrega", "text": "Migrações devem ser versionadas e compatíveis com o período de convivência entre versões quando necessário. Planeje rollback e recuperação de dados; reverter binário não desfaz uma migração destrutiva. O estudo pode ser todo local, sem contratar hospedagem."}], "code": "package main\nimport (\n    \"fmt\"\n    \"runtime/debug\"\n)\nfunc main() {\n    info, ok := debug.ReadBuildInfo()\n    if !ok { fmt.Println(\"sem metadados\"); return }\n    fmt.Println(\"Go:\", info.GoVersion)\n    fmt.Println(\"Módulo:\", info.Main.Path)\n}\n", "expected": "Metadados dependem do toolchain e do modo de build usados localmente.", "quiz": {"question": "Voltar o binário para a versão anterior sempre desfaz uma migração de banco?", "options": ["Sim", "Não; esquema e dados precisam de estratégia própria", "Só com container", "Se usar go build"], "answer": 1, "explanation": "Rollback de aplicação e recuperação de esquema/dados são problemas relacionados, mas diferentes."}, "exercises": [{"id": 1, "title": "Pipeline mínimo", "prompt": "Escreva a sequência de verificações para sua API e diga qual problema cada uma detecta.", "hint": "Inclua correção, races e dependências.", "solution": "go test ./..., go vet ./..., go test -race ./... onde suportado, govulncheck ./... instalado conforme documentação e go build ./.... Verifique formatação segundo a política do projeto.", "criteria": ["Cada etapa tem uma finalidade.", "Não trata todas como prova universal."]}, {"id": 2, "title": "Container com contexto", "prompt": "Desenhe um build multi-stage e liste arquivos necessários no runtime além do binário.", "hint": "HTTPS e timezones podem exigir dados do sistema.", "solution": "Considere certificados CA, base de fuso quando necessária, bibliotecas exigidas por cgo e diretórios com permissões adequadas. Não assuma que scratch serve para qualquer build.", "criteria": ["Sem segredo na imagem.", "Considera dependências reais de execução."]}, {"id": 3, "title": "Migração compatível", "prompt": "Planeje a troca de um campo sem quebrar a versão anterior ainda em execução.", "hint": "Expanda, migre dados e só então remova o legado.", "solution": "Adicione a nova estrutura de forma compatível, publique código que consiga conviver, migre/verifique dados e remova o antigo em etapa posterior. Defina observação e recuperação.", "criteria": ["Prevê coexistência.", "Separa remoção destrutiva."]}], "source": "https://go.dev/doc/security/", "caution": "", "local": true, "minutes": 60}, {"id": 34, "level": 12, "week": 34, "title": "Por dentro do toolchain e das fronteiras", "goal": "Investigar AST, compilação e integrações de baixo nível com cuidado.", "theory": [{"title": "Da sintaxe ao executável", "text": "go/parser produz uma árvore sintática; go/ast permite percorrê-la; go/types ajuda na análise de tipos. O compilador possui fases e representações internas como SSA, mas elas não são APIs estáveis da linguagem. Comece com um analisador pequeno antes de ler o compilador inteiro."}, {"title": "unsafe e cgo são fronteiras", "text": "unsafe permite operações fora de algumas garantias do sistema de tipos. Regras de ponteiros, alinhamento e vida dos objetos importam. cgo integra código C, com custos de chamada, regras de passagem de ponteiros e dependências de build. Não use essas ferramentas para eliminar uma checagem sem prova e medição."}, {"title": "Wasm e trilhas de aprofundamento", "text": "Go tem alvos WebAssembly e WASI com restrições próprias; consulte a documentação do alvo e da versão. Como especialização, escolha compiladores, runtime, bibliotecas, redes ou ferramentas. Leia código e testes da implementação sem tratar um detalhe interno como promessa de compatibilidade."}], "code": "package main\nimport (\n    \"fmt\"\n    \"go/ast\"\n    \"go/parser\"\n    \"go/token\"\n)\nfunc main() {\n    src := \"package exemplo; func Somar(a, b int) int { return a+b }\"\n    f, err := parser.ParseFile(token.NewFileSet(), \"exemplo.go\", src, 0)\n    if err != nil { fmt.Println(err); return }\n    ast.Inspect(f, func(n ast.Node) bool {\n        if fn, ok := n.(*ast.FuncDecl); ok { fmt.Println(fn.Name.Name) }\n        return true\n    })\n}\n", "expected": "Somar", "quiz": {"question": "A representação interna SSA do compilador é uma API estável da linguagem?", "options": ["Sim", "Não; é detalhe de implementação", "É um arquivo go.mod", "É um tipo de canal"], "answer": 1, "explanation": "O contrato da linguagem e as APIs documentadas são distintos dos detalhes internos do compilador."}, "exercises": [{"id": 1, "title": "Analisador pequeno", "prompt": "Conte funções declaradas em um arquivo e liste seus nomes usando parser e AST.", "hint": "FuncDecl representa declaração de função/método; literais de função são outro nó.", "solution": "Parseie, trate erro e percorra a AST coletando *ast.FuncDecl. Documente se métodos e funções anônimas entram no critério.", "criteria": ["Critério definido.", "Não usa regex como parser da linguagem."]}, {"id": 2, "title": "Decisão sobre cgo", "prompt": "Uma biblioteca C resolve um problema inexistente em Go puro. Liste custos e alternativas antes de integrá-la.", "hint": "Considere build, portabilidade, memória e chamada.", "solution": "Avalie bibliotecas Go, processo separado e cgo. Se escolher cgo, documente regras de ponteiro, lib nativa, plataformas, testes e benefício mensurável.", "criteria": ["Compara alternativas.", "Inclui restrições operacionais."]}, {"id": 3, "title": "Plano de especialização", "prompt": "Escolha runtime, ferramentas ou Wasm e crie três investigações reproduzíveis além deste curso.", "hint": "Cada investigação precisa de uma pergunta e evidência.", "solution": "Exemplo de ferramentas: localizar funções, resolver tipos com go/types e criar um analisador com testes de diagnóstico. Registre docs/versão e resultados reais.", "criteria": ["Três perguntas concretas.", "Resultados podem ser reproduzidos."]}], "source": "https://pkg.go.dev/go/parser", "caution": "", "local": true, "minutes": 60}, {"id": 35, "level": 12, "week": 35, "title": "Falhas distribuídas, filas e consistência", "goal": "Projetar repetição e recuperação sem prometer exatamente uma vez.", "theory": [{"title": "A rede deixa resultados desconhecidos", "text": "Timeout não prova que o servidor não executou. Um serviço pode confirmar uma mudança e perder a resposta. Retries cegos podem multiplicar efeitos. Defina chave de idempotência, retenção, resultado reaproveitado e tratamento de chaves reutilizadas com payload diferente."}, {"title": "Entrega e efeito são contratos diferentes", "text": "Filas com entrega ao menos uma vez podem repetir mensagens. O consumidor precisa deduplicar com persistência e uma fronteira transacional adequada. Um map em memória só demonstra a ideia; não resolve reinício, múltiplas instâncias nem concorrência de produção."}, {"title": "Consistência com limites explícitos", "text": "Outbox, retries com backoff e jitter, limite de tentativas, dead-letter e observabilidade formam uma política de recuperação. Cancelamento não é compensação de efeito já confirmado. Defina invariáveis do negócio e escolha consistência conforme a fronteira; não adicione distribuição sem necessidade."}], "code": "package main\nimport \"fmt\"\nfunc main() {\n    vistos := make(map[string]bool)\n    for _, evento := range []string{\"confirmar-7\", \"confirmar-7\", \"confirmar-8\"} {\n        if vistos[evento] { continue }\n        vistos[evento] = true\n        fmt.Println(\"processado\", evento)\n    }\n}\n", "expected": "processado confirmar-7\nprocessado confirmar-8", "quiz": {"question": "Um map de deduplicação em memória resolve repetição após reiniciar o processo?", "options": ["Sim", "Não; o estado se perde e falta uma fronteira durável", "Só com Mutex", "Somente para strings"], "answer": 1, "explanation": "Mutex resolve acesso concorrente local, mas não persistência, reinício ou coordenação entre instâncias."}, "exercises": [{"id": 1, "title": "Idempotência durável", "prompt": "Projete confirmação de OS com chave única, resultado persistido e payload identificado.", "hint": "A deduplicação e o efeito precisam compartilhar a fronteira de consistência.", "solution": "Persista chave, hash do pedido e resultado. Garanta unicidade no banco e atomicidade com a mudança de negócio. Payload diferente com a mesma chave deve ser recusado conforme contrato.", "criteria": ["Sobrevive a reinício.", "Não aceita reutilização ambígua da chave."]}, {"id": 2, "title": "Mensagem problemática", "prompt": "Defina política para uma tarefa que falha sempre.", "hint": "Repetir infinitamente sem visibilidade consome recursos.", "solution": "Use limite de tentativas e atraso, classifique falhas transitórias/permanentes, mova para estado de revisão/dead-letter e permita reprocessamento auditável depois da correção.", "criteria": ["Limita custo.", "Há diagnóstico e recuperação."]}, {"id": 3, "title": "Timeout após commit", "prompt": "Explique ao operador o que fazer quando a confirmação retornou timeout, mas pode ter sido aplicada.", "hint": "Um novo pedido sem a mesma identidade pode repetir o efeito.", "solution": "Consulte o resultado pela chave/OS ou repita com a mesma chave idempotente. Mostre estado pendente de verificação até obter uma resposta confiável.", "criteria": ["Reconhece resultado desconhecido.", "Evita duplicação."]}], "source": "https://go.dev/blog/context", "caution": "O map do exemplo é apenas didático. A deduplicação do projeto deve ser persistente e transacional.", "local": true, "minutes": 60}, {"id": 36, "level": 12, "week": 36, "title": "Projeto final e defesa técnica", "goal": "Demonstrar o fluxo completo e justificar decisões.", "theory": [{"title": "O produto final", "text": "Construa Central de serviços: agendamento gera OS; técnico envia evidências e identifica equipamento; operação confere fotos e confirma; a confirmação baixa o equipamento e alimenta o fechamento. Use dados fictícios e comece sem integração com serviços reais. Uma despesa extra pertence a uma OS específica e exige descrição e comprovante; taxa de deslocamento é definida operacionalmente."}, {"title": "A prova está nos cenários", "text": "Mostre o caminho feliz e falhas: acesso indevido, JSON inválido, evidência ausente conforme regra definida, repetição da confirmação, concorrência, falha de banco, cancelamento e timeout após commit. A conferência operacional não deve exigir uma nova leitura de IMEI quando a instalação já o registrou. Bloqueio operacional pode existir como serviço independente."}, {"title": "Defenda as escolhas", "text": "Entregue README de execução local, migrações, testes, limites conhecidos, decisões de arquitetura, demonstração e um relatório de perfil. Escolha uma área para aprofundar depois. Concluir 288 horas não transforma alguém automaticamente em sênior; autonomia vem de prática, revisão e operação de sistemas reais."}], "code": "package main\nimport (\n    \"errors\"\n    \"fmt\"\n)\ntype Ordem struct { Confirmada bool; Equipamento string }\nfunc (o *Ordem) Confirmar() error {\n    if o.Confirmada { return nil }\n    if o.Equipamento == \"\" { return errors.New(\"instalação sem vínculo de equipamento\") }\n    o.Confirmada = true\n    return nil\n}\nfunc main() {\n    o := Ordem{Equipamento:\"000123456789012\"}\n    if err := o.Confirmar(); err != nil { fmt.Println(err); return }\n    if err := o.Confirmar(); err != nil { fmt.Println(err); return }\n    fmt.Println(o.Confirmada)\n}\n", "expected": "true", "quiz": {"question": "Qual é a melhor evidência de domínio do projeto final?", "options": ["Quantidade de pastas", "Fluxo executável, testes de falha e decisões justificadas", "Somente o README", "Um resultado sem reprodução"], "answer": 1, "explanation": "Competência se demonstra com comportamento verificável e capacidade de explicar decisões, custos e limites."}, "exercises": [{"id": 1, "title": "Fluxo completo", "prompt": "Implemente a primeira fatia vertical: criar OS, vincular equipamento e confirmar com baixa transacional.", "hint": "Faça um caminho ponta a ponta antes de ampliar módulos.", "solution": "Entregue API, banco e teste de integração dessa fatia. A confirmação utiliza o vínculo já persistido. A ausência de dupla baixa deve ser garantida no banco, não apenas por um bool em memória.", "criteria": ["Demonstração reprodutível.", "Repetição e concorrência não duplicam o efeito."]}, {"id": 2, "title": "Falhas e despesas", "prompt": "Acrescente despesa vinculada à OS com descrição e comprovante, mais taxa operacional de deslocamento.", "hint": "Separe quem declara a despesa de quem a aprova.", "solution": "Modele vínculo obrigatório, status de aprovação e acesso ao comprovante. Inclua teste de ausência de descrição/evidência e autorização para taxa operacional.", "criteria": ["Despesa pertence a uma OS.", "Descrição e comprovante são exigidos."]}, {"id": 3, "title": "Defesa final", "prompt": "Prepare uma demonstração de 10 minutos e uma revisão das principais decisões e limitações.", "hint": "Mostre uma falha e a recuperação, além do caminho feliz.", "solution": "Apresente fluxo, testes, perfil, modelo de autorização, transação e idempotência. Diga o que ainda não está pronto para produção e qual seria a próxima investigação.", "criteria": ["Inclui evidência de execução.", "Limitações são explícitas."]}], "source": "https://go.dev/doc/", "caution": "O exemplo ilustra uma regra em memória. A entrega final exige autorização, persistência, transação e testes de concorrência.", "local": true, "minutes": 60}]};
